# ── /analise/v2-shadow-live ───────────────────────────────────────────────────

@app.route("/analise/v2-shadow-live")
def analise_v2_shadow_live():  # noqa: C901
    """V2.1 Shadow gate dashboard derived from micro_absorption_snapshots.

    Minimal production-safe implementation: no executor calls, no trading side
    effects, and no additional writes. The worker keeps collecting snapshots;
    this endpoint materializes the active shadow gate from those snapshots.
    """
    def _pct(v):
        return "—" if v is None else f"{v*100:.1f}%"

    def _money(v):
        return "—" if v is None else f"${v:,.0f}"

    def _fmt_dt(v):
        if v is None:
            return "—"
        try:
            return v.strftime("%m-%d %H:%M:%S")
        except Exception:
            return str(v)

    try:
        days = int(request.args.get("days", 3))
        fmt = request.args.get("format", "html")
        limit = int(request.args.get("limit", 200))
        tp_pct = float(request.args.get("tp_pct", 0.75))
        sl_pct = float(request.args.get("sl_pct", 0.25))
        sc_pol = request.args.get("same_candle_policy", "conservative_sl_first")

        decision_age = int(request.args.get(
            "decision_age",
            os.getenv("V2_SHADOW_DECISION_AGE_SEC")
            or os.getenv("V2_DECISION_AGE_SEC", "10"),
        ))
        net_window = request.args.get("net_window", os.getenv("V2_NET_WINDOW", "live_5s"))
        net_min = float(request.args.get("net_min", os.getenv("V2_NET_MIN", "-2")))
        min_pool = float(request.args.get("min_pool", os.getenv("V2_MIN_POOL_SOL", "10")))
        min_events = int(request.args.get("min_events", os.getenv("V2_MIN_EVENTS", "5")))
        min_bounce_pct = float(request.args.get(
            "min_bounce_pct", os.getenv("V2_MIN_BOUNCE_PCT", "0.30")))
        max_bounce_pct = float(request.args.get(
            "max_bounce_pct", os.getenv("V2_MAX_BOUNCE_PCT", "0.50")))
        scope = request.args.get("candidate_scope", os.getenv("V2_CANDIDATE_SCOPE", "mint_first"))
        if scope not in ("mint_first", "bottom_events"):
            scope = "mint_first"

        events_dict, ticks_dict, bounce_dict = _v2_load_data(days)
        cands = _v2_build_candidates(
            events_dict, ticks_dict, bounce_dict,
            decision_age=decision_age,
            net_window=net_window,
            net_min=net_min,
            min_pool=min_pool,
            min_events=min_events,
            min_bounce_pct=min_bounce_pct,
            max_bounce_pct=max_bounce_pct,
            tp_pct=tp_pct,
            sl_pct=sl_pct,
            sc_pol=sc_pol,
            candidate_scope=scope,
            v1_match_mode="first_after_v2",
        )
        stats = _v2_stats(cands, tp_pct, sl_pct)
        recent = sorted(cands, key=lambda c: c.get("ts_snap") or c.get("ts_min"), reverse=True)[:limit]

        gate = {
            "version": "v2.1_early_bounce_2026_06_03",
            "source": "derived_from_micro_absorption_snapshots",
            "shadow_enabled": os.getenv("V2_SHADOW_ENABLED", "true").lower() == "true",
            "trading_enabled": os.getenv("TRADING_ENABLED", "false").lower() == "true",
            "decision_age": decision_age,
            "net_window": net_window,
            "net_min": net_min,
            "min_pool": min_pool,
            "min_events": min_events,
            "min_bounce_pct": min_bounce_pct,
            "max_bounce_pct": max_bounce_pct,
            "candidate_scope": scope,
            "tp_pct": tp_pct,
            "sl_pct": sl_pct,
            "same_candle_policy": sc_pol,
            "days": days,
        }

        if fmt == "json":
            def _clean_candidate(c: dict) -> dict:
                out = dict(c)
                for k in ("ts_min", "ts_snap"):
                    v = out.get(k)
                    if hasattr(v, "isoformat"):
                        out[k] = v.isoformat()
                out.pop("v1_match", None)
                return out
            return jsonify({
                "gate": gate,
                "stats": stats,
                "recent": [_clean_candidate(c) for c in recent],
            })

        def _card(label: str, value: str, color: str = "#111") -> str:
            return (
                "<div class='card'>"
                f"<b style='color:{color}'>{value}</b>"
                f"<small>{label}</small>"
                "</div>"
            )

        rows = []
        for c in recent:
            outcome = c.get("outcome") or "—"
            oc_col = "#080" if outcome == "tp" else "#b00" if outcome == "sl" else "#777"
            match = c.get("match_status") or "no_v1"
            rows.append(
                "<tr>"
                f"<td>{_fmt_dt(c.get('ts_snap'))}</td>"
                f"<td>{_fmt_dt(c.get('ts_min'))}</td>"
                f"<td>{c.get('symbol') or '?'}</td>"
                f"<td><code>{str(c.get('mint') or '')[:8]}</code></td>"
                f"<td>{c.get('bottom_age_actual') or 0:.1f}s</td>"
                f"<td>{_money(c.get('mc_current'))}</td>"
                f"<td>{_pct(c.get('bounce_pct_now'))}</td>"
                f"<td>{_pct(c.get('drop_from_mig'))}</td>"
                f"<td>{c.get('pool_quote') or 0:.1f}</td>"
                f"<td>{c.get('net_val') if c.get('net_val') is not None else '—'}</td>"
                f"<td>{c.get('events_val') or 0}</td>"
                f"<td style='color:{oc_col};font-weight:bold'>{outcome}</td>"
                f"<td>{_pct(c.get('max_gain'))}</td>"
                f"<td>{_pct(c.get('max_dd'))}</td>"
                f"<td>{match}</td>"
                f"<td>{_pct(c.get('v1_entry_improvement'))}</td>"
                "</tr>"
            )

        qs = (
            f"days={days}&decision_age={decision_age}&net_window={net_window}"
            f"&net_min={net_min}&min_pool={min_pool}&min_events={min_events}"
            f"&min_bounce_pct={min_bounce_pct}&max_bounce_pct={max_bounce_pct}"
            f"&candidate_scope={scope}&tp_pct={tp_pct}&sl_pct={sl_pct}"
        )
        warn = "" if not gate["trading_enabled"] else (
            "<div class='warn'>⚠️ TRADING_ENABLED=true detectado. Este endpoint não compra, "
            "mas o executor global está habilitado.</div>"
        )

        html = f"""<!DOCTYPE html><html><head><meta charset="utf-8">
<title>V2 Shadow Live</title>
<meta http-equiv="refresh" content="120">
<style>
body{{font-family:monospace;font-size:12px;padding:14px;background:#fafafa;color:#111}}
a{{color:#06c}} table{{border-collapse:collapse;margin-top:10px;background:white}}
td,th{{padding:3px 6px;border:1px solid #ccc;font-size:11px}} th{{background:#eee}}
.card{{display:inline-block;margin:3px;padding:7px 10px;background:white;border:1px solid #ddd;border-radius:5px;min-width:110px;text-align:center}}
.card b{{display:block;font-size:16px}} .card small{{display:block;color:#777;font-size:10px}}
.warn{{background:#fff3cd;border:1px solid #f2d27b;padding:8px;margin:8px 0}}
.note{{color:#666}}
</style></head><body>
<h2>🧠 V2 Shadow Live — {gate['version']}</h2>
<p class="note">
  Fonte: micro_absorption_snapshots → materialização do gate ativo. Research/dry-run only; não chama executor e não faz swap.<br>
  gate: scope={scope} decision_age={decision_age}s {net_window}≥{net_min} min_pool={min_pool}SOL min_events={min_events} bounce=[{min_bounce_pct:.0%},{max_bounce_pct:.0%}] | últimos {days}d
</p>
{warn}
<p>
  <a href="?{qs}&format=json">JSON</a> |
  <a href="/analise/v2-vs-v1-entry?{qs}">v2-vs-v1-entry</a> |
  <a href="/analise/v2-decision-tape?{qs}">Decision Tape</a> |
  <a href="/analise/v2-brain-report?days={days}">Brain Report</a>
</p>
<div>
  {_card('candidatos', str(stats['n']))}
  {_card('WR_ex_chop', _pct(stats['wr_ex_chop']), '#080' if (stats['wr_ex_chop'] or 0) >= 0.30 else '#b00')}
  {_card('TP', str(stats['tp']))}
  {_card('SL', str(stats['sl']))}
  {_card('no_exit', str(stats['no_exit']))}
  {_card('EV_all', _pct(stats['expectancy_all']), '#080' if (stats['expectancy_all'] or 0) > 0 else '#b00')}
  {_card('median_dd', _pct(stats['median_max_dd']))}
  {_card('V1 matches', str(stats['n_v1']))}
  {_card('V1 entry impr', _pct(stats['avg_entry_improvement']))}
</div>
<h3>Últimos {len(recent)} sinais derivados</h3>
<table>
<tr><th>ts_signal</th><th>ts_min</th><th>symbol</th><th>mint</th><th>age</th><th>entry_mc</th><th>bounce</th><th>drop</th><th>pool</th><th>{net_window}</th><th>events</th><th>outcome</th><th>max_gain</th><th>max_dd</th><th>V1</th><th>V1 impr</th></tr>
{''.join(rows)}
</table>
</body></html>"""
        return render_template_string(html)
    except Exception as e:
        import traceback
        return f"<pre>Erro: {e}\n\n{traceback.format_exc()}</pre>", 500

# /analise/v2-brain-report — Grid cartesiano + Recomendação Bigplayer
# ══════════════════════════════════════════════════════════════════════════════

@app.route("/analise/v2-brain-report")
def analise_v2_brain_report():  # noqa: C901
    """Grid cartesiano de parâmetros V2 com recomendação automática.

    Carrega dados UMA VEZ e aplica todas as combinações em memória.

    Query params:
      days=14            janela de dados
      format=html|json   saída
      min_n=10           mínimo de candidatos para combo ser válido
      tp_pct=0.75        take-profit %
      sl_pct=0.25        stop-loss %
      same_candle_policy=conservative_sl_first|optimistic_tp_first|midpoint
      top=50             top N combos por tabela
      include_details=0  se 1, inclui lista de candidatos
      candidate_scope=all|mint_first|bottom_events
      mode=fast|full     fast evita travar o web; full varre o grid completo
      max_runtime_sec=20 orçamento de tempo para retornar parcial em vez de congelar
    """
    import itertools, statistics as _stats_mod, time as _time_mod

    try:
        started_at = _time_mod.monotonic()
        days            = int(request.args.get("days", 14))
        fmt             = request.args.get("format", "html")
        min_n           = int(request.args.get("min_n", 10))
        tp_pct          = float(request.args.get("tp_pct", 0.75))
        sl_pct          = float(request.args.get("sl_pct", 0.25))
        sc_pol          = request.args.get("same_candle_policy", "conservative_sl_first")
        top_n           = int(request.args.get("top", 50))
        include_details = request.args.get("include_details", "0") == "1"
        scope_override  = request.args.get("candidate_scope", "all")
        mode            = request.args.get("mode", "fast")
        max_runtime_sec = float(request.args.get("max_runtime_sec", 20))

        # ── Grid de parâmetros ────────────────────────────────────────────────
        # Fast is the default because the full Cartesian grid can exceed one
        # Gunicorn request window while recomputing outcomes thousands of times.
        # Use mode=full explicitly when running offline/worker-side diagnostics.
        if mode == "full":
            DECISION_AGES = [3, 5, 10, 15, 30]
            NET_MINS      = [-5.0, -3.0, -2.0, -1.0, 0.0, 1.0, 2.0]
            MIN_POOLS     = [10.0, 20.0, 40.0, 80.0]
            MIN_EVENTS    = [1, 3, 5, 8]
            BOUNCE_RANGES = [
                (None, None),
                (None, 0.15),
                (0.15, 0.30),
                (None, 0.30),
                (0.30, 0.50),
                (0.50, 1.00),
            ]
        else:
            mode = "fast"
            DECISION_AGES = [10, 15]
            NET_MINS      = [-5.0, -2.0, 0.0]
            MIN_POOLS     = [10.0, 20.0]
            MIN_EVENTS    = [3, 5]
            BOUNCE_RANGES = [
                (None, None),
                (None, 0.15),
                (0.15, 0.30),
                (None, 0.30),
                (0.30, 0.50),
            ]

        BOUNCE_RANGE_LABELS = {
            (None, None):     "qualquer",
            (None, 0.15):     "<15%",
            (0.15, 0.30):     "15-30%",
            (None, 0.30):     "0-30%",
            (0.30, 0.50):     "30-50%",
            (0.50, 1.00):     "50-100%",
        }
        # Windows disponíveis — restringir ao que existe nos dados
        ALL_NET_WINDOWS = ["live_5s", "live_10s", "live_30s", "live_60s",
                           "pre_10s", "pre_30s"]
        SCOPES = (["mint_first", "bottom_events"]
                  if scope_override == "all"
                  else [scope_override if scope_override in ("mint_first", "bottom_events")
                        else "mint_first"])

        # ── Carregar dados UMA VEZ ────────────────────────────────────────────
        events_dict, ticks_dict, bounce_dict = _v2_load_data(days)

        if not events_dict:
            msg = "Sem dados em micro_absorption_snapshots nos últimos {} dias.".format(days)
            if fmt == "json":
                return jsonify({"error": msg}), 200
            return f"<p style='font-family:monospace'>{msg}</p>", 200

        # Detectar windows com dados não-NULL
        available_windows: list = []
        for nw in ALL_NET_WINDOWS:
            net_col = nw + "_net"
            has_data = any(
                s.get(net_col) is not None
                for snaps in events_dict.values()
                for s in snaps
            )
            if has_data:
                available_windows.append(nw)

        if not available_windows:
            available_windows = ["live_10s"]  # fallback
        if mode == "fast":
            preferred_windows = ["live_10s", "live_5s"]
            fast_windows = [nw for nw in preferred_windows if nw in available_windows]
            available_windows = fast_windows or available_windows[:2]

        # ── Helpers ───────────────────────────────────────────────────────────
        def _score_ev_risk(st: dict) -> float | None:
            ev = st.get("expectancy_all")
            if ev is None:
                return None
            dd = (st.get("p75_max_dd") or
                  st.get("median_max_dd") or 0)
            n  = st.get("n", 0)
            return ev - abs(dd) * 0.10 - max(0, 20 - n) * 0.002

        def _confidence_label(st: dict) -> str:
            n   = st.get("n", 0)
            ev  = st.get("expectancy_all")
            wr  = st.get("wr_ex_chop")
            scr = _score_ev_risk(st)
            if n < 10 or ev is None or ev <= 0:
                return "weak_sample"
            if n < 20:
                return "watch"
            if scr is None or scr <= 0:
                return "watch"
            if wr is None or wr < 0.30:
                return "candidate"
            if wr < 0.40 or n < 40:
                return "strong"
            return "production_candidate"

        # ── Grid loop ─────────────────────────────────────────────────────────
        all_combos: list = []
        total_combos_tested = 0
        partial = False

        for scope, da, nw, net_min, mp, mev, (bmin, bmax) in itertools.product(
                SCOPES, DECISION_AGES, available_windows,
                NET_MINS, MIN_POOLS, MIN_EVENTS, BOUNCE_RANGES):
            if (_time_mod.monotonic() - started_at) > max_runtime_sec:
                partial = True
                break
            total_combos_tested += 1

            cands = _v2_build_candidates(
                events_dict, ticks_dict, bounce_dict,
                decision_age=da,
                net_window=nw,
                net_min=net_min,
                min_pool=mp,
                min_events=mev,
                min_bounce_pct=bmin,
                max_bounce_pct=bmax,
                tp_pct=tp_pct,
                sl_pct=sl_pct,
                sc_pol=sc_pol,
                candidate_scope=scope,
                v1_match_mode="first_after_v2",
            )
            if not cands:
                continue

            st = _v2_stats(cands, tp_pct, sl_pct)
            n  = st.get("n", 0)
            ev = st.get("expectancy_all")

            if n < min_n or ev is None or ev <= 0:
                continue

            scr = _score_ev_risk(st)
            lbl = _confidence_label(st)

            combo = {
                "scope":         scope,
                "decision_age":  da,
                "net_window":    nw,
                "net_min":       net_min,
                "min_pool":      mp,
                "min_events":    mev,
                "bounce_range":  BOUNCE_RANGE_LABELS.get((bmin, bmax), f"{bmin}-{bmax}"),
                "bounce_min":    bmin,
                "bounce_max":    bmax,
                "score_ev_risk": scr,
                "confidence":    lbl,
                **st,
                "candidates":    cands if include_details else None,
            }
            all_combos.append(combo)

        if not all_combos:
            msg = ("Nenhuma combinação válida (n≥{} e EV>0). "
                   "Acumule mais dados.").format(min_n)
            if fmt == "json":
                return jsonify({"error": msg, "days": days}), 200
            return f"<p style='font-family:monospace'>{msg}</p>", 200

        # ── Ordenações ────────────────────────────────────────────────────────
        top_by_score = sorted(
            all_combos,
            key=lambda c: c["score_ev_risk"] or -999,
            reverse=True
        )[:top_n]

        top_by_ev = sorted(
            all_combos,
            key=lambda c: c.get("expectancy_all") or -999,
            reverse=True
        )[:top_n]

        risk_ranked = sorted(
            all_combos,
            key=lambda c: abs(c.get("median_max_dd") or 0)
        )[:top_n]

        # ── Agregações ────────────────────────────────────────────────────────
        # Scope comparison
        scope_comp: dict = {}
        for scope in SCOPES:
            sc_combos = [c for c in all_combos if c["scope"] == scope]
            if sc_combos:
                best = max(sc_combos, key=lambda c: c["score_ev_risk"] or -999)
                scope_comp[scope] = {
                    "n_combos":    len(sc_combos),
                    "best_score":  best["score_ev_risk"],
                    "best_ev":     best.get("expectancy_all"),
                    "best_wr":     best.get("wr_ex_chop"),
                }

        # Bounce range comparison — best combo per range
        bounce_comp: dict = {}
        for _, (bmin, bmax) in enumerate(BOUNCE_RANGES):
            lbl_br = BOUNCE_RANGE_LABELS[(bmin, bmax)]
            br_combos = [c for c in all_combos if c["bounce_min"] == bmin and c["bounce_max"] == bmax]
            if br_combos:
                best = max(br_combos, key=lambda c: c["score_ev_risk"] or -999)
                bounce_comp[lbl_br] = {
                    "n_combos":   len(br_combos),
                    "best_score": best["score_ev_risk"],
                    "best_ev":    best.get("expectancy_all"),
                    "best_wr":    best.get("wr_ex_chop"),
                    "best_n":     best.get("n"),
                }

        # Net window comparison — best combo per window
        nw_comp: dict = {}
        for nw in available_windows:
            nw_combos = [c for c in all_combos if c["net_window"] == nw]
            if nw_combos:
                best = max(nw_combos, key=lambda c: c["score_ev_risk"] or -999)
                nw_comp[nw] = {
                    "n_combos":   len(nw_combos),
                    "best_score": best["score_ev_risk"],
                    "best_ev":    best.get("expectancy_all"),
                    "best_wr":    best.get("wr_ex_chop"),
                    "best_n":     best.get("n"),
                }

        # ── Bigplayer Recommendation ──────────────────────────────────────────
        has_prod   = any(c["confidence"] == "production_candidate" for c in all_combos)
        has_strong = any(c["confidence"] in ("strong", "production_candidate") for c in all_combos)
        best_ev    = max((c.get("expectancy_all") or 0) for c in all_combos)
        best_n     = max(c.get("n", 0) for c in all_combos)

        if best_n < 10:
            rec_label = "NÃO PRODUZIR"
            rec_detail = (f"n_max={best_n} — insuficiente para qualquer conclusão. "
                          "Acumule ≥30 bounces com outcomes GMGN confirmados.")
        elif best_ev <= 0:
            rec_label = "COLETAR MAIS DADOS"
            rec_detail = ("EV≤0 em todas as combinações válidas. "
                          "Sinal não lucrativo com os parâmetros atuais. "
                          "Verifique se os outcomes de TP/SL estão corretos.")
        elif has_prod:
            best_c = max(
                [c for c in all_combos if c["confidence"] == "production_candidate"],
                key=lambda c: c["score_ev_risk"] or -999
            )
            rec_label = "MICRO-PROD CONTROLADA"
            rec_detail = (
                f"decision_age={best_c['decision_age']}s  "
                f"net_window={best_c['net_window']}  "
                f"net_min={best_c['net_min']}  "
                f"min_pool={best_c['min_pool']}  "
                f"min_events={best_c['min_events']}  "
                f"bounce={best_c['bounce_range']}  "
                f"scope={best_c['scope']}  "
                f"→  n={best_c['n']}  WR={best_c.get('wr_ex_chop') or 0:.1%}  "
                f"EV={best_c.get('expectancy_all') or 0:+.3f}  "
                f"score={best_c['score_ev_risk']:+.4f}"
            )
        elif has_strong:
            best_c = max(
                [c for c in all_combos if c["confidence"] in ("strong", "production_candidate")],
                key=lambda c: c["score_ev_risk"] or -999
            )
            rec_label = "DRY-RUN V2"
            rec_detail = (
                f"decision_age={best_c['decision_age']}s  "
                f"net_window={best_c['net_window']}  "
                f"net_min={best_c['net_min']}  "
                f"min_pool={best_c['min_pool']}  "
                f"min_events={best_c['min_events']}  "
                f"bounce={best_c['bounce_range']}  "
                f"scope={best_c['scope']}  "
                f"→  n={best_c['n']}  WR={best_c.get('wr_ex_chop') or 0:.1%}  "
                f"EV={best_c.get('expectancy_all') or 0:+.3f}  "
                f"score={best_c['score_ev_risk']:+.4f}"
            )
        else:
            rec_label = "COLETAR MAIS DADOS"
            best_c = max(all_combos, key=lambda c: c["score_ev_risk"] or -999)
            rec_detail = (
                f"Melhor combo: confidence={best_c['confidence']}  "
                f"n={best_c['n']}  EV={best_c.get('expectancy_all') or 0:+.3f}. "
                "Aguarde ≥40 candidatos com WR≥40% confirmados."
            )

        # ── JSON output ───────────────────────────────────────────────────────
        if fmt == "json":
            def _clean(c):
                out = {k: v for k, v in c.items() if k != "candidates"}
                # make datetime JSON-serialisable
                for k, v in out.items():
                    if hasattr(v, "isoformat"):
                        out[k] = v.isoformat()
                return out
            return jsonify({
                "recommendation": {"label": rec_label, "detail": rec_detail},
                "n_valid_combos": len(all_combos),
                "top_by_score":  [_clean(c) for c in top_by_score[:20]],
                "top_by_ev":     [_clean(c) for c in top_by_ev[:20]],
                "scope_comp":    scope_comp,
                "bounce_comp":   bounce_comp,
                "nw_comp":       nw_comp,
                "params": {
                    "days": days, "min_n": min_n, "tp_pct": tp_pct,
                    "sl_pct": sl_pct, "sc_pol": sc_pol,
                    "available_windows": available_windows,
                    "mode": mode,
                    "partial": partial,
                    "total_combos_tested": total_combos_tested,
                    "elapsed_sec": round(_time_mod.monotonic() - started_at, 3),
                },
            })

        # ── HTML output ───────────────────────────────────────────────────────
        CONF_COLOR = {
            "weak_sample":          "#888",
            "watch":                "#aaa66b",
            "candidate":            "#6baaa6",
            "strong":               "#6ba66b",
            "production_candidate": "#2a8a2a",
        }
        REC_COLOR = {
            "NÃO PRODUZIR":         "#c0392b",
            "COLETAR MAIS DADOS":   "#d68910",
            "DRY-RUN V2":           "#1a7fa8",
            "MICRO-PROD CONTROLADA":"#2a8a2a",
        }

        def _pct(v):
            return f"{v:.1%}" if v is not None else "—"

        def _f3(v):
            return f"{v:+.3f}" if v is not None else "—"

        def _f2(v):
            return f"{v:.2f}" if v is not None else "—"

        def _combo_row(c, rank=None):
            conf_col = CONF_COLOR.get(c["confidence"], "#888")
            rank_td  = f"<td>{rank}</td>" if rank is not None else ""
            return (
                f"<tr>"
                f"{rank_td}"
                f"<td>{c['scope']}</td>"
                f"<td>{c['decision_age']}s</td>"
                f"<td>{c['net_window']}</td>"
                f"<td>{c['net_min']:+.0f}</td>"
                f"<td>{c['min_pool']:.0f}</td>"
                f"<td>{c['min_events']}</td>"
                f"<td>{c['bounce_range']}</td>"
                f"<td>{c['n']}</td>"
                f"<td>{_pct(c.get('wr_ex_chop'))}</td>"
                f"<td>{_f3(c.get('expectancy_all'))}</td>"
                f"<td>{_f3(c.get('score_ev_risk'))}</td>"
                f"<td style='color:{conf_col};font-weight:bold'>{c['confidence']}</td>"
                f"<td>{_pct(c.get('median_max_dd'))}</td>"
                f"<td>{_pct(c.get('avg_entry_improvement'))}</td>"
                f"</tr>"
            )

        COMBO_TH = (
            "<tr><th>#</th><th>scope</th><th>age</th><th>window</th>"
            "<th>net_min</th><th>pool</th><th>evts</th><th>bounce</th>"
            "<th>n</th><th>WR</th><th>EV</th><th>score</th>"
            "<th>confidence</th><th>med_dd</th><th>v1_impr</th></tr>"
        )

        top_score_rows = "\n".join(
            _combo_row(c, i+1) for i, c in enumerate(top_by_score)
        )
        top_ev_rows = "\n".join(
            _combo_row(c, i+1) for i, c in enumerate(top_by_ev)
        )
        risk_rows = "\n".join(
            _combo_row(c, i+1) for i, c in enumerate(risk_ranked)
        )

        # Scope comparison table
        scope_rows = ""
        for sc, sv in scope_comp.items():
            scope_rows += (
                f"<tr><td>{sc}</td><td>{sv['n_combos']}</td>"
                f"<td>{_f3(sv['best_score'])}</td>"
                f"<td>{_f3(sv['best_ev'])}</td>"
                f"<td>{_pct(sv['best_wr'])}</td></tr>"
            )

        # Bounce range comparison table
        bounce_rows = ""
        for br_lbl, bv in sorted(bounce_comp.items(), key=lambda x: -(x[1]["best_score"] or -999)):
            avg_n_str = f"{bv['best_n']}"
            bounce_rows += (
                f"<tr><td>{br_lbl}</td><td>{bv['n_combos']}</td>"
                f"<td>{_f3(bv['best_score'])}</td>"
                f"<td>{_f3(bv['best_ev'])}</td>"
                f"<td>{_pct(bv['best_wr'])}</td>"
                f"<td>{avg_n_str}</td></tr>"
            )

        # Net window comparison table
        nw_rows = ""
        for nw_lbl, nv in sorted(nw_comp.items(), key=lambda x: -(x[1]["best_score"] or -999)):
            nw_rows += (
                f"<tr><td>{nw_lbl}</td><td>{nv['n_combos']}</td>"
                f"<td>{_f3(nv['best_score'])}</td>"
                f"<td>{_f3(nv['best_ev'])}</td>"
                f"<td>{_pct(nv['best_wr'])}</td>"
                f"<td>{nv['best_n']}</td></tr>"
            )

        rec_col = REC_COLOR.get(rec_label, "#888")
        now_str = datetime.now().strftime("%Y-%m-%d %H:%M UTC")

        html = f"""<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>V2 Brain Report</title>
<style>
  body{{font-family:monospace;background:#111;color:#ddd;padding:20px;}}
  h1{{color:#f0c060;}} h2{{color:#88aaff;border-bottom:1px solid #444;padding-bottom:4px;}}
  table{{border-collapse:collapse;width:100%;margin-bottom:20px;}}
  th,td{{border:1px solid #444;padding:4px 8px;text-align:left;font-size:12px;}}
  th{{background:#222;color:#aaa;}}
  tr:nth-child(even){{background:#1a1a1a;}}
  .rec{{font-size:18px;font-weight:bold;padding:12px 20px;border-radius:6px;
        background:#1e1e1e;border-left:6px solid {rec_col};color:{rec_col};}}
  .sub{{font-size:12px;color:#aaa;margin-top:6px;}}
  .meta{{color:#666;font-size:11px;}}
  a{{color:#88aaff;}}
</style>
</head>
<body>
<h1>V2 Brain Report</h1>
<p class="meta">Gerado: {now_str} | janela: {days}d | min_n: {min_n} |
TP: {tp_pct:.0%} SL: {sl_pct:.0%} | mode: {mode} | partial: {partial} |
combos testados: {total_combos_tested} | combos válidos: {len(all_combos)} |
windows: {', '.join(available_windows)}</p>
<p class="meta">Padrão é <code>mode=fast</code> para não travar o web. Use <code>?mode=full&format=json</code> somente se precisar da varredura completa.</p>

<h2>1. Executive Summary</h2>
<div class="rec">{rec_label}</div>
<div class="sub" style="margin-top:8px;padding:8px;background:#1a1a1a;border-radius:4px;">
{rec_detail}
</div>

<h2>2. Top {len(top_by_score)} por score_ev_risk</h2>
<table>
{COMBO_TH}
{top_score_rows}
</table>

<h2>3. Top {len(top_by_ev)} por expectancy_all</h2>
<table>
{COMBO_TH}
{top_ev_rows}
</table>

<h2>4. Risk Table (menor drawdown mediano)</h2>
<table>
{COMBO_TH}
{risk_rows}
</table>

<h2>5. Scope Comparison</h2>
<table>
<tr><th>scope</th><th>n_combos</th><th>best_score</th><th>best_EV</th><th>best_WR</th></tr>
{scope_rows}
</table>

<h2>6. Bounce Range Comparison</h2>
<table>
<tr><th>bounce_range</th><th>n_combos</th><th>best_score</th><th>best_EV</th><th>best_WR</th><th>best_n</th></tr>
{bounce_rows}
</table>

<h2>7. Net Window Comparison</h2>
<table>
<tr><th>window</th><th>n_combos</th><th>best_score</th><th>best_EV</th><th>best_WR</th><th>best_n</th></tr>
{nw_rows}
</table>

<h2>8. Recomendação Bigplayer</h2>
<div class="rec">{rec_label}</div>
<div class="sub" style="margin-top:8px;padding:8px 12px;background:#1a1a1a;border-radius:4px;white-space:pre-wrap;">{rec_detail}</div>
<p class="meta" style="margin-top:16px;">
  score_ev_risk = expectancy_all − |p75_dd|×0.10 − max(0, 20−n)×0.002<br>
  confidence: weak_sample → watch → candidate → strong → production_candidate<br>
  v1_entry_improvement: positivo = V2 entrou mais barato que V1 (bs_entry/entry_mc − 1)<br>
  <a href="/analise/v2-brain-report?days={days}&format=json">→ JSON</a>
  &nbsp;|&nbsp;
  <a href="/analise/v2-threshold-grid?days={days}">→ Threshold Grid</a>
  &nbsp;|&nbsp;
  <a href="/analise/v2-decision-tape?days={days}">→ Decision Tape</a>
</p>
</body>
</html>"""

        return render_template_string(html)

    except Exception as e:
        import traceback
        return f"<pre>Erro: {e}\n\n{traceback.format_exc()}</pre>", 500



@app.route("/debug/env-check")
def debug_env_check():
    """Mostra variáveis de ambiente relevantes do processo atual."""
    import os as _os
    keys = ["TELEGRAM_TOKEN", "TELEGRAM_CHAT", "DATABASE_URL", "RAILWAY_SERVICE_NAME",
            "RAILWAY_ENVIRONMENT", "RAILWAY_GIT_BRANCH", "RUN_BOT_SERVICES"]
    return jsonify({k: (_os.getenv(k, "NÃO DEFINIDA")[:20] + "..." if _os.getenv(k) and len(_os.getenv(k)) > 20 else _os.getenv(k, "NÃO DEFINIDA")) for k in keys})


@app.route("/debug/test-telegram")
def debug_test_telegram():
    """Envia mensagem de teste e retorna a resposta real do Telegram para diagnóstico."""
    import os as _os
    import requests as _requests
    from datetime import datetime, timezone
    token = _os.getenv("TELEGRAM_TOKEN", "")
    chat  = _os.getenv("TELEGRAM_CHAT", "")
    now   = datetime.now(timezone.utc).strftime("%d/%m/%Y %H:%M UTC")
    if not token or not chat:
        return jsonify({"ok": False, "error": "variáveis não encontradas", "token": bool(token), "chat": bool(chat)}), 400
    try:
        resp = _requests.post(
            f"https://api.telegram.org/bot{token}/sendMessage",
            json={"chat_id": chat, "text": f"✅ *NeideBOT — Telegram OK!* _{now}_", "parse_mode": "Markdown"},
            timeout=10,
        )
        return jsonify({
            "telegram_response": resp.json(),
            "token_preview": token[:10] + "...",
            "chat_id": chat,
        }), 200 if resp.ok else 400
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


@app.route("/debug/schema")
def debug_schema():
    """Read-only runtime schema healthcheck. Does not run migrations/DDL."""
    try:
        schema = db.check_runtime_schema()
    except Exception as e:
        schema = {"ok": False, "error": str(e)}

    status = 200 if schema.get("ok") else 503
    if request.args.get("format") == "json":
        return jsonify(schema), status

    CSS = ("<style>body{background:#0d1117;color:#e6edf3;font:13px/1.5 monospace;padding:20px}"
           "h2{color:#58a6ff}.ok{color:#3fb950}.bad{color:#f85149}.warn{color:#d29922}"
           "table{border-collapse:collapse;width:100%;margin-top:12px}"
           "td,th{padding:6px 8px;border-bottom:1px solid #30363d;text-align:left;vertical-align:top}"
           "th{color:#8b949e;background:#161b22}code{white-space:pre-wrap}"
           "a{color:#58a6ff}</style>")
    ok = bool(schema.get("ok"))
    h = f"<html><head><meta charset='utf-8'>{CSS}</head><body>"
    h += "<h2>Runtime Schema Healthcheck</h2>"
    status_label = "OK" if ok else "MISSING / ERROR"
    status_class = "ok" if ok else "bad"
    h += f"<p>Status: <b class='{status_class}'>{status_label}</b> "
    h += "&nbsp;|&nbsp; <a href='?format=json'>JSON</a> &nbsp;|&nbsp; "
    h += "<a href='javascript:location.reload()'>Refresh</a></p>"
    h += "<p class='warn'>Read-only: este endpoint não roda ALTER TABLE. "
    h += "Se falhar, rode a one-off migration: "
    h += "<code>RUN_DB_MIGRATIONS=1 python migrate.py</code>.</p>"
    if schema.get("error"):
        h += f"<p class='bad'>Erro: <code>{str(schema.get('error')).replace('<','&lt;')}</code></p>"
    h += "<table><tr><th>Tabela</th><th>Status</th><th>Colunas faltando</th><th>Coverage</th></tr>"
    for table, info in (schema.get("tables") or {}).items():
        exists = info.get("exists")
        missing = info.get("missing_columns") or []
        row_ok = exists and not missing
        if exists:
            present_count = info.get("present_required_count", 0)
            required_count = info.get("required_count", len(missing))
            coverage = f"{present_count}/{required_count}"
        else:
            coverage = "0/?"
        h += "<tr>"
        h += f"<td><b>{table}</b></td>"
        row_class = "ok" if row_ok else "bad"
        row_status = "OK" if row_ok else ("missing table" if not exists else "missing cols")
        h += f"<td class='{row_class}'>{row_status}</td>"
        h += f"<td><code>{', '.join(missing) if missing else '—'}</code></td>"
        h += f"<td>{coverage}</td>"
        h += "</tr>"
    h += "</table></body></html>"
    return h, status

# ==============================================================================
# /debug/db-locks — visibilidade de atividade e locks do PostgreSQL
# ==============================================================================

@app.route("/debug/db-locks")
def debug_db_locks():
    """Mostra atividade atual do PostgreSQL — útil para diagnosticar deadlocks e contention."""
    import psycopg2
    from psycopg2.extras import RealDictCursor

    conn = psycopg2.connect(db.DATABASE_URL, cursor_factory=RealDictCursor)
    conn.autocommit = True
    try:
        with conn.cursor() as cur:
            cur.execute("""
                SELECT
                    a.pid,
                    a.state,
                    a.wait_event_type,
                    a.wait_event,
                    extract(epoch from (now() - a.query_start))::int AS age_sec,
                    left(a.query, 300) AS query,
                    pg_blocking_pids(a.pid) AS blocked_by
                FROM pg_stat_activity a
                WHERE a.datname = current_database()
                  AND a.pid != pg_backend_pid()
                ORDER BY a.query_start NULLS LAST
                LIMIT 30
            """)
            rows = cur.fetchall()
    finally:
        conn.close()

    if request.args.get("format") == "json":
        from flask import jsonify
        return jsonify({"locks": [dict(r) for r in rows]})

    # HTML simples
    CSS = ("<style>body{background:#0d1117;color:#e6edf3;font:12px/1.6 monospace;padding:20px}"
           "h2{color:#58a6ff}table{border-collapse:collapse;width:100%;white-space:pre-wrap}"
           "th{background:#161b22;padding:6px 10px;text-align:left;font-size:11px;color:#8b949e;"
           "border-bottom:2px solid #30363d}"
           "td{padding:4px 10px;border-bottom:1px solid #21262d;font-size:11px;vertical-align:top}"
           ".blocked{background:#3a1a1a}.waiting{background:#3a2a1a}"
           "a{color:#58a6ff}</style>")
    h = f"<html><head><meta charset='utf-8'>{CSS}</head><body>"
    h += "<h2>DB Activity / Locks</h2>"
    h += f"<p style='color:#8b949e'>{len(rows)} conexões ativas &nbsp;|&nbsp; "
    h += "<a href='?format=json'>JSON</a> &nbsp;|&nbsp; "
    h += "<a href='javascript:location.reload()'>Refresh</a></p>"
    h += "<table><tr><th>PID</th><th>State</th><th>Wait</th><th>Age(s)</th>"
    h += "<th>Blocked by</th><th>Query</th></tr>"
    for r in rows:
        blocked = r.get("blocked_by") or []
        row_class = "blocked" if blocked else ("waiting" if r.get("wait_event") else "")
        h += f"<tr class='{row_class}'>"
        h += f"<td>{r['pid']}</td>"
        h += f"<td>{r['state'] or ''}</td>"
        h += f"<td>{(r['wait_event_type'] or '')}/{(r['wait_event'] or '')}</td>"
        h += f"<td>{r['age_sec'] or 0}</td>"
        h += f"<td>{'['+','.join(str(x) for x in blocked)+']' if blocked else ''}</td>"
        h += f"<td><code>{(r['query'] or '').replace('<','&lt;')}</code></td></tr>"
    h += "</table></body></html>"
    return h


@app.route("/analise/bounce-funnel")
def analise_bounce_funnel():  # noqa: C901
    """Por que migrações com fundo não viram sinal? Diagnóstico token a token."""
    import psycopg2.extras
    from datetime import date as _date

    since_default = "2026-05-26"
    since_ts = request.args.get("since", since_default) or since_default

    CSS = (
        "<style>"
        "body{background:#0d1117;color:#e6edf3;font:12px/1.6 monospace;padding:20px}"
        "h2{color:#58a6ff;margin-top:24px;border-bottom:1px solid #30363d;padding-bottom:6px}"
        "h3{color:#79c0ff;margin-top:16px}"
        "table{border-collapse:collapse;width:100%;margin-bottom:16px}"
        "th{background:#161b22;padding:6px 10px;text-align:left;font-size:11px;"
        "color:#8b949e;border-bottom:2px solid #30363d}"
        "td{padding:4px 10px;border-bottom:1px solid #21262d;font-size:11px;vertical-align:top}"
        ".dim{color:#8b949e}.hi{color:#e6edf3;font-weight:bold}"
        ".good{color:#3fb950}.warn{color:#f0883e}.bad{color:#f85149}"
        ".bar{display:inline-block;height:10px;vertical-align:middle}"
        "a{color:#58a6ff}"
        "</style>"
    )

    h = f"<html><head><meta charset='utf-8'>{CSS}</head><body>"
    h += "<h2>\U0001f50d Bounce Funnel — Por que não estamos entrando?</h2>"
    h += f"<p class='dim'>Dados desde <b>{since_ts}</b>. "
    h += "<a href='?since=2026-05-26'>26/mai (limpo)</a> &nbsp;|&nbsp; "
    h += "<a href='?since=2026-06-01'>01/jun</a> &nbsp;|&nbsp; "
    h += "<a href='?since=2026-06-05'>05/jun</a> &nbsp;|&nbsp; "
    h += "<a href='javascript:location.reload()'>↻ Refresh</a></p>"

    try:
        conn = psycopg2.connect(db.DATABASE_URL)
        conn.autocommit = True
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

        try:
            d0 = _date.fromisoformat(since_ts)
            n_days = max(1, (_date.today() - d0).days)
        except Exception:
            n_days = 14

        # ── 1. FUNIL BÁSICO ────────────────────────────────────────────────────────
        h += "<h2>1 · Funil de Conversão</h2>"

        cur.execute("SELECT COUNT(*) AS n FROM migrations WHERE ts_migration >= %(s)s::timestamptz", {"s": since_ts})
        n_mig = cur.fetchone()["n"]

        cur.execute("SELECT COUNT(*) AS n FROM migrations WHERE ts_migration >= %(s)s::timestamptz AND mc_bottom IS NOT NULL", {"s": since_ts})
        n_bottom = cur.fetchone()["n"]

        cur.execute("SELECT COUNT(*) AS n FROM bounce_signals WHERE ts_signal >= %(s)s::timestamptz", {"s": since_ts})
        n_bs = cur.fetchone()["n"]

        cur.execute("SELECT COUNT(*) AS n FROM trades WHERE ts_signal >= %(s)s::timestamptz", {"s": since_ts})
        n_tr = cur.fetchone()["n"]

        cur.execute("""
            SELECT
                SUM(CASE WHEN status IN ('tp','trailing_active') THEN 1 ELSE 0 END) AS tp,
                SUM(CASE WHEN status='sl' THEN 1 ELSE 0 END) AS sl
            FROM trades WHERE ts_signal >= %(s)s::timestamptz AND status IN ('tp','trailing_active','sl')
        """, {"s": since_ts})
        r = cur.fetchone()
        n_tp, n_sl = (r["tp"] or 0), (r["sl"] or 0)

        def pct(a, b):
            return f"{100*a/b:.0f}%" if b else "—"

        steps = [
            ("Migrações detectadas", n_mig, "100%", "#58a6ff"),
            ("Com mc_bottom confirmado (60min)", n_bottom, pct(n_bottom, n_mig), "#79c0ff"),
            ("Bounce signals disparados", n_bs, pct(n_bs, n_bottom), "#f0883e"),
            ("Trades executados", n_tr, pct(n_tr, n_bs), "#3fb950"),
            ("TPs confirmados", n_tp, pct(n_tp, n_tr), "#3fb950"),
            ("SLs", n_sl, pct(n_sl, n_tr), "#f85149"),
        ]
        h += "<table><tr><th>Etapa</th><th>N</th><th>Taxa</th><th>Barra</th></tr>"
        mx = max(n_mig, 1)
        for label, n, rate, color in steps:
            bw = max(1, int(250 * n / mx))
            h += f"<tr><td class='hi'>{label}</td><td>{n}</td><td style='color:{color}'>{rate}</td>"
            h += f"<td><span class='bar' style='width:{bw}px;background:{color}'></span></td></tr>"
        h += "</table>"

        missed = n_bottom - n_bs
        h += f"<p class='warn'>⚠️ <b>{missed}</b> migrações tiveram fundo confirmado mas NUNCA dispararam sinal. "
        h += "Veja a análise abaixo.</p>"

        # ── 2. POR QUE OS 99 TOKENS NÃO DISPARARAM? ───────────────────────────────
        h += "<h2>2 · Por Que os Tokens com Fundo Não Dispararam Sinal?</h2>"
        h += "<p class='dim'>Para cada migração com mc_bottom, buscamos o pico máximo nos <i>token_ticks</i> "
        h += "dentro de 20 min pós-migração e calculamos o bounce estimado. "
        h += "Tokens sem bounce_signal mostram qual filtro teria barrado.</p>"

        cur.execute("""
            SELECT
                m.mint,
                m.token_nome        AS symbol,
                m.ts_migration,
                m.mc_migration,
                m.mc_bottom,
                -- pico nos ticks dentro de 20 min (janela A.5)
                (SELECT MAX(tt.mc)
                 FROM token_ticks tt
                 WHERE tt.mint = m.mint
                   AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                   AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'
                ) AS mc_peak_60min,
                -- número de ticks disponíveis na janela
                (SELECT COUNT(*)
                 FROM token_ticks tt
                 WHERE tt.mint = m.mint
                   AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                   AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'
                ) AS tick_count,
                bs.id               AS bounce_id,
                bs.bounce_pct       AS bs_bounce_pct,
                bs.elapsed_sec      AS bs_elapsed,
                bs.pool_quote_at_signal AS bs_pool,
                t.status            AS trade_status
            FROM migrations m
            LEFT JOIN bounce_signals bs ON bs.mint = m.mint
            LEFT JOIN trades t ON t.mint = m.mint
                AND t.ts_signal >= m.ts_migration - INTERVAL '2 minutes'
            WHERE m.ts_migration >= %(s)s::timestamptz
              AND m.mc_bottom IS NOT NULL
              AND m.mc_bottom > 0
            ORDER BY m.ts_migration DESC
        """, {"s": since_ts})
        all_rows = cur.fetchall()

        # Classify each token
        cats = {
            "fired": [],
            "bounce_insuficiente": [],    # max tick < 30% — token nunca subiu o suficiente
            "bounce_grande_demais": [],   # > 100% — tardio (A.8)
            "sem_ticks": [],              # não temos token_ticks → erpc/kline não cobriu
            "spike_possivel": [],         # bounce >= 30% e <= 100% mas sinal não disparou → problema real
        }
        for r in all_rows:
            if r["bounce_id"]:
                cats["fired"].append(r)
                continue
            mb = r["mc_bottom"]
            mp = r["mc_peak_60min"]
            ticks = r["tick_count"] or 0
            if ticks == 0:
                cats["sem_ticks"].append(r)
            elif mp is None or mb is None or mb <= 0:
                cats["sem_ticks"].append(r)
            else:
                bp_est = (mp - mb) / mb
                if bp_est > 1.00:
                    cats["bounce_grande_demais"].append(r)
                elif bp_est >= 0.30:
                    cats["spike_possivel"].append(r)
                else:
                    cats["bounce_insuficiente"].append(r)

        cat_labels = {
            "fired": ("Sinal disparado ✅", "#3fb950"),
            "bounce_insuficiente": ("Bounce estimado < 30% (token não subiu o suficiente)", "#8b949e"),
            "sem_ticks": ("Sem token_ticks na janela (erpc não cobriu)", "#f0883e"),
            "spike_possivel": ("Bounce ≥ 30% nos ticks mas SINAL NÃo DISPAROU ⚠️", "#f85149"),
            "bounce_grande_demais": ("Bounce > 100% (entrada tardia — A.8)", "#f0883e"),
        }
        total_with_bottom = len(all_rows)
        h += "<table><tr><th>Categoria</th><th>N</th><th>%</th><th>Barra</th><th>Interpretação</th></tr>"
        for cat, (label, color) in cat_labels.items():
            n = len(cats[cat])
            rate = f"{100*n/total_with_bottom:.0f}%" if total_with_bottom else "—"
            bw = max(1, int(200 * n / max(total_with_bottom, 1)))
            h += f"<tr><td style='color:{color}'><b>{label}</b></td><td>{n}</td><td>{rate}</td>"
            h += f"<td><span class='bar' style='width:{bw}px;background:{color}'></span></td>"
            interp = ""
            if cat == "bounce_insuficiente":
                interp = "Normal — dado limpo, a maioria dos tokens simplesmente não bouncea o suficiente"
            elif cat == "sem_ticks":
                interp = "Problema de cobertura — erpc não subscreveu ou token saiu antes do fundo"
            elif cat == "spike_possivel":
                interp = "\U0001f6a8 SINAL PERDIDO — token bounceou mas o detector não disparou"
            elif cat == "bounce_grande_demais":
                interp = "A.8 barrou — entrada tardia (bounce > 100%)"
            elif cat == "fired":
                interp = f"Viraram {n_bs} bounce_signals, {n_tr} trades"
            h += f"<td class='dim'>{interp}</td></tr>"
        h += "</table>"

        # ── 3. TOKENS COM BOUNCE REAL MAS SEM SINAL (CASOS CRÍTICOS) ─────────────
        if cats["spike_possivel"]:
            h += "<h2>3 · \U0001f6a8 Casos Críticos — Bounce Real Sem Sinal</h2>"
            h += "<p class='warn'>Esses tokens tiveram bounce ≥ 30% nos token_ticks mas o scanner <b>não disparou sinal</b>. "
            h += "Indica problema real: erpc viu o evento mas _check_bounce falhou, ou os ticks chegaram depois da janela A.5.</p>"
            h += ("<table><tr><th>Símbolo</th><th>Data</th><th>mc_mig</th><th>mc_bottom</th>"
                  "<th>mc_peak (ticks)</th><th>Bounce est.</th><th>Ticks</th>"
                  "<th>A.5 elapsed</th><th>DexScreener</th></tr>")
            for r in sorted(cats["spike_possivel"], key=lambda x: x["ts_migration"] or 0, reverse=True):
                mb = r["mc_bottom"] or 0
                mp = r["mc_peak_60min"] or 0
                bp_est = (mp - mb) / mb * 100 if mb > 0 else 0
                ts_str = r["ts_migration"].strftime("%m/%d %H:%M") if r["ts_migration"] else "—"
                sym = r["symbol"] or (r["mint"][:8] if r["mint"] else "?")
                dex_url = f"https://dexscreener.com/solana/{r['mint']}" if r["mint"] else "#"
                h += (f"<tr>"
                      f"<td><a href='{dex_url}' target='_blank'>{sym}</a></td>"
                      f"<td class='dim'>{ts_str}</td>"
                      f"<td class='dim'>${(r['mc_migration'] or 0)/1000:.0f}k</td>"
                      f"<td>${mb/1000:.0f}k</td>"
                      f"<td>${mp/1000:.0f}k</td>"
                      f"<td class='bad'><b>{bp_est:.0f}%</b></td>"
                      f"<td class='dim'>{r['tick_count'] or 0}</td>"
                      f"<td class='dim'>—</td>"
                      f"<td><a href='{dex_url}' target='_blank'>chart</a></td>"
                      f"</tr>")
            h += "</table>"
        else:
            h += "<h2>3 · Casos Críticos</h2>"
            h += "<p class='good'>✅ Nenhum token com bounce real perdido no período. "
            h += "Os tokens sem sinal genuinamente não bouncearam o suficiente.</p>"

        # ── 4. DISTRIBUIÇÃO DE BOUNCE ESTIMADO (TODOS OS TOKENS COM BOTTOM) ───────
        h += "<h2>4 · Distribuição de Bounce Estimado — TODOS os Tokens com Fundo</h2>"
        h += "<p class='dim'>Bounce estimado = (mc_peak nos ticks até 60min) / mc_bottom. "
        h += "Inclui tanto os que dispararam sinal quanto os que não dispararam.</p>"

        cur.execute("""
            SELECT
                width_bucket(
                    GREATEST(0, (mc_peak - mc_bottom) / NULLIF(mc_bottom, 0)) * 100,
                    0, 200, 20
                ) AS bucket,
                MIN(GREATEST(0, (mc_peak - mc_bottom) / NULLIF(mc_bottom, 0)) * 100) AS lo,
                MAX(GREATEST(0, (mc_peak - mc_bottom) / NULLIF(mc_bottom, 0)) * 100) AS hi,
                COUNT(*) AS n,
                SUM(CASE WHEN has_signal THEN 1 ELSE 0 END) AS n_signal
            FROM (
                SELECT
                    m.mc_bottom,
                    COALESCE(
                        (SELECT MAX(tt.mc) FROM token_ticks tt
                         WHERE tt.mint = m.mint
                           AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                           AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'),
                        m.mc_bottom
                    ) AS mc_peak,
                    (bs.id IS NOT NULL) AS has_signal
                FROM migrations m
                LEFT JOIN bounce_signals bs ON bs.mint = m.mint
                WHERE m.ts_migration >= %(s)s::timestamptz
                  AND m.mc_bottom IS NOT NULL AND m.mc_bottom > 0
            ) sub
            GROUP BY bucket ORDER BY bucket
        """, {"s": since_ts})
        dist_rows = cur.fetchall()

        if dist_rows:
            max_n = max((r["n"] for r in dist_rows), default=1)
            h += ("<table><tr><th>Bounce estimado (60min)</th><th>N tokens</th>"
                  "<th>Com sinal</th><th>Sem sinal</th><th>Barra</th></tr>")
            for r in dist_rows:
                lo = r["lo"] or 0
                hi_v = r["hi"] or 0
                n = r["n"]
                n_sig = r["n_signal"] or 0
                n_nosig = n - n_sig
                bw = max(1, int(200 * n / max_n))
                # Color: red = below threshold, green = above
                color = "#3fb950" if lo >= 30 else "#f85149" if lo < 10 else "#f0883e"
                marker = " ← threshold 30%" if abs(lo - 30) < 8 else ""
                h += (f"<tr><td>{lo:.0f}–{hi_v:.0f}%{marker}</td>"
                      f"<td>{n}</td>"
                      f"<td class='good'>{n_sig}</td>"
                      f"<td class='warn'>{n_nosig}</td>"
                      f"<td><span class='bar' style='width:{bw}px;background:{color}'></span></td></tr>")
            h += "</table>"

        # ── 5. SENSIBILIDADE DO THRESHOLD (baseado em bounce estimado real) ────────
        h += "<h2>5 · Sensibilidade do BOUNCE_MIN_PCT — Sinais Possíveis/dia</h2>"
        h += "<p class='dim'>Estimativa baseada no bounce máximo real de cada token (token_ticks até 60min). "
        h += "Conta quantos tokens poderiam ter disparado sinal com cada threshold.</p>"

        # Collect bounce estimates
        bounces_est = []
        for r in all_rows:
            mb = r["mc_bottom"]
            mp = r["mc_peak_60min"]
            if mb and mp and mb > 0:
                bounces_est.append((mp - mb) / mb)

        thresholds = [0.10, 0.15, 0.20, 0.25, 0.30, 0.35, 0.40, 0.50, 0.60, 0.75, 1.00]
        h += ("<table><tr><th>BOUNCE_MIN_PCT</th><th>Tokens possíveis</th>"
              "<th>%</th><th>Est. sinais/dia</th><th></th></tr>")
        total_est = len(bounces_est)
        for thr in thresholds:
            count = sum(1 for bp in bounces_est if bp >= thr)
            rate = f"{100*count/total_est:.0f}%" if total_est else "—"
            per_day = f"{count/n_days:.1f}" if n_days else "—"
            is_cur = abs(thr - 0.30) < 0.001
            style = " style='background:#1a2a1a'" if is_cur else ""
            note = "← ATUAL" if is_cur else ""
            h += (f"<tr{style}><td class='hi'>{thr:.0%}</td>"
                  f"<td>{count}</td><td>{rate}</td><td>{per_day}</td>"
                  f"<td class='dim'>{note}</td></tr>")
        h += "</table>"

        # ── 6. TABELA DETALHADA DOS BOUNCE SIGNALS ────────────────────────────────
        h += "<h2>6 · Bounce Signals Detalhados — Métricas Completas</h2>"
        h += "<p class='dim'>Apenas os sinais que PASSARAM todos os filtros. Links para DexScreener.</p>"

        cur.execute("""
            SELECT
                bs.id, bs.symbol, bs.mint, bs.ts_signal,
                bs.elapsed_sec, bs.mc_migration, bs.mc_min, bs.mc_at_signal,
                bs.drop_from_mig, bs.bounce_pct,
                bs.pool_quote_at_signal,
                bs.net_sol_flow,
                bs.rise_buy_vol, bs.rise_sell_vol, bs.rise_net_flow, bs.rise_events,
                bs.absorption_buy_vol, bs.absorption_sell_vol, bs.absorption_events,
                bs.buy_concentration,
                bs.data_quality,
                t.status AS trade_status, t.pnl_pct_real
            FROM bounce_signals bs
            LEFT JOIN trades t ON t.mint = bs.mint
                AND t.ts_signal >= bs.ts_signal - INTERVAL '30 seconds'
                AND t.ts_signal <= bs.ts_signal + INTERVAL '30 seconds'
            WHERE bs.ts_signal >= %(s)s::timestamptz
            ORDER BY bs.ts_signal DESC
            LIMIT 200
        """, {"s": since_ts})
        det_rows = cur.fetchall()

        h += ("<table><tr><th>Símb</th><th>Hora</th>"
              "<th>elapsed</th><th>mc_mig</th><th>mc_min</th><th>mc_sig</th>"
              "<th>drop</th><th>bounce</th>"
              "<th>pool</th><th>net_flow</th>"
              "<th>rise_buy</th><th>rise_sell</th><th>r_ev</th>"
              "<th>abs_buy</th><th>abs_sell</th><th>a_ev</th>"
              "<th>buy_conc</th><th>qual</th><th>trade</th></tr>")

        for r in det_rows:
            bp = (r["bounce_pct"] or 0) * 100
            drop = (r["drop_from_mig"] or 0) * 100
            el = r["elapsed_sec"] or 0
            pool = r["pool_quote_at_signal"]
            net = r["net_sol_flow"]
            ts_s = r["ts_signal"].strftime("%m/%d %H:%M") if r["ts_signal"] else "—"
            sym = r["symbol"] or (r["mint"][:8] if r["mint"] else "?")
            dex = f"https://dexscreener.com/solana/{r['mint']}" if r["mint"] else "#"

            bp_col = "#3fb950" if bp >= 30 else "#f85149"
            el_col = "#f85149" if el > 1200 else "#3fb950"
            pool_s = "{:.1f}".format(pool) if pool else "—"
            pool_col = "#3fb950" if pool and pool >= 15 else "#f0883e" if pool else "#8b949e"
            net_s = "{:+.2f}".format(net) if net is not None else "—"
            net_col = "#3fb950" if net and net > 1 else "#f85149" if net and net < -5 else "#8b949e"
            qual = r["data_quality"] or "?"
            q_col = "#3fb950" if qual == "good" else "#f0883e" if qual == "ok" else "#f85149"

            trade_s = "—"
            if r["trade_status"]:
                pnl = r["pnl_pct_real"]
                pnl_s = "{:+.0f}%".format(pnl * 100) if pnl is not None else ""
                t_col = "#3fb950" if r["trade_status"] in ("tp", "trailing_active") else "#f85149" if r["trade_status"] == "sl" else "#8b949e"
                trade_s = f"<span style='color:{t_col}'>{r['trade_status']} {pnl_s}</span>"

            def _sol(v):
                return "{:.2f}".format(v) if v else "—"

            h += (f"<tr>"
                  f"<td><a href='{dex}' target='_blank'>{sym}</a></td>"
                  f"<td class='dim'>{ts_s}</td>"
                  f"<td style='color:{el_col}'>{el//60}m{el%60}s</td>"
                  f"<td class='dim'>${(r['mc_migration'] or 0)/1000:.0f}k</td>"
                  f"<td class='dim'>${(r['mc_min'] or 0)/1000:.0f}k</td>"
                  f"<td class='dim'>${(r['mc_at_signal'] or 0)/1000:.0f}k</td>"
                  f"<td class='warn'>-{drop:.0f}%</td>"
                  f"<td style='color:{bp_col}'><b>{bp:.0f}%</b></td>"
                  f"<td style='color:{pool_col}'>{pool_s}</td>"
                  f"<td style='color:{net_col}'>{net_s}</td>"
                  f"<td>{_sol(r['rise_buy_vol'])}</td>"
                  f"<td>{_sol(r['rise_sell_vol'])}</td>"
                  f"<td class='dim'>{r['rise_events'] or '—'}</td>"
                  f"<td>{_sol(r['absorption_buy_vol'])}</td>"
                  f"<td>{_sol(r['absorption_sell_vol'])}</td>"
                  f"<td class='dim'>{r['absorption_events'] or '—'}</td>"
                  f"<td class='dim'>{'{:.2f}'.format(r['buy_concentration']) if r['buy_concentration'] else '—'}</td>"
                  f"<td style='color:{q_col}'>{qual}</td>"
                  f"<td>{trade_s}</td>"
                  f"</tr>")
        h += "</table>"

        # ── 7. RESUMO ─────────────────────────────────────────────────────────────
        h += "<h2>7 · Resumo Executivo</h2>"
        n_sem_ticks = len(cats["sem_ticks"])
        n_insuf = len(cats["bounce_insuficiente"])
        n_spike = len(cats["spike_possivel"])
        n_tardio = len(cats["bounce_grande_demais"])

        h += "<table><tr><th>Métrica</th><th>Valor</th><th>Interpretação</th></tr>"
        h += f"<tr><td>Período</td><td class='hi'>{n_days} dias</td><td class='dim'>Desde {since_ts}</td></tr>"
        h += f"<tr><td>Migrações</td><td>{n_mig}</td><td class='dim'>{n_mig/n_days:.1f}/dia</td></tr>"
        h += f"<tr><td>Com fundo confirmado</td><td>{n_bottom}</td><td class='dim'>{100*n_bottom/max(n_mig,1):.0f}% das migrações</td></tr>"
        h += f"<tr><td>Bounce signals</td><td class='hi'>{n_bs}</td><td class='dim'>{n_bs/n_days:.1f}/dia</td></tr>"

        # Main diagnosis
        if n_insuf > n_sem_ticks:
            main_diag = (f"\U0001f7e1 A maioria ({n_insuf} tokens = {100*n_insuf/max(n_bottom,1):.0f}%) "
                         "simplesmente não bounceou o suficiente (<30%). "
                         "Com dados reais (erpc), os bounces são menores do que os dados históricos corrompidos. "
                         "Considere <b>BOUNCE_MIN_PCT=0.20</b> para capturar mais sinais válidos.")
        elif n_sem_ticks > n_insuf:
            main_diag = (f"\U0001f534 Problema de cobertura de ticks: {n_sem_ticks} tokens sem token_ticks. "
                         "Significa que o erpc não subscreveu o mint ou o token saiu da janela antes de gerar ticks. "
                         "Verificar subscrição erpc no HotMonitor.")
        else:
            main_diag = "\U0001f7e1 Distribuição equilibrada — sem causa dominante única."

        h += f"<tr><td>Diagnóstico principal</td><td colspan='2'>{main_diag}</td></tr>"

        if n_spike > 0:
            h += (f"<tr><td style='color:#f85149'>Sinais perdidos críticos</td>"
                  f"<td style='color:#f85149'>{n_spike}</td>"
                  f"<td class='dim'>Tokens que bouncearam ≥ 30% mas o sinal não disparou. "
                  f"Investigar se erpc estava subscrito e se _check_bounce rodou.</td></tr>")

        avg_bs_bp = sum(float(r["bs_bounce_pct"] or 0) for r in cats["fired"]) / max(len(cats["fired"]), 1) * 100
        h += f"<tr><td>bounce_pct médio (sinais disparados)</td><td class='hi'>{avg_bs_bp:.1f}%</td><td class='dim'>Com dados limpos</td></tr>"

        est_with_20 = sum(1 for bp in bounces_est if bp >= 0.20)
        h += (f"<tr><td>Se BOUNCE_MIN_PCT=0.20</td><td class='warn'>{est_with_20} sinais possíveis</td>"
              f"<td class='dim'>{est_with_20/n_days:.1f}/dia estimado</td></tr>")
        h += "</table>"

        cur.close()
        conn.close()

    except Exception as e:
        import traceback
        h += f"<pre style='color:#f85149'>ERRO: {e}\n{traceback.format_exc()}</pre>"

    h += "</body></html>"
    return h



@app.route("/analise/filter-calibration")
def analise_filter_calibration():  # noqa: C901
    """Calibração de filtros do zero com dados limpos (pós-2026-05-26)."""
    import psycopg2.extras
    from datetime import date as _date

    since_ts = request.args.get("since", "2026-05-26") or "2026-05-26"

    CSS = (
        "<style>"
        "body{background:#0d1117;color:#e6edf3;font:12px/1.6 monospace;padding:20px}"
        "h2{color:#58a6ff;margin-top:28px;border-bottom:1px solid #30363d;padding-bottom:6px}"
        "h3{color:#79c0ff;margin-top:18px}"
        "table{border-collapse:collapse;width:100%;margin-bottom:14px}"
        "th{background:#161b22;padding:6px 10px;text-align:left;font-size:11px;"
        "color:#8b949e;border-bottom:2px solid #30363d}"
        "td{padding:4px 10px;border-bottom:1px solid #21262d;font-size:11px;vertical-align:top}"
        ".good{color:#3fb950}.warn{color:#f0883e}.bad{color:#f85149}"
        ".dim{color:#8b949e}.hi{color:#e6edf3;font-weight:bold}"
        ".bar{display:inline-block;height:10px;vertical-align:middle}"
        ".note{background:#1a1f2e;padding:8px 12px;border-left:3px solid #388bfd;"
        "margin:8px 0;font-size:11px}"
        "a{color:#58a6ff}"
        "</style>"
    )
    h = f"<html><head><meta charset='utf-8'>{CSS}</head><body>"
    h += "<h2>\U0001f9ea Filter Calibration — Do Zero com Dados Limpos</h2>"
    h += f"<p class='dim'>Período desde <b>{since_ts}</b> (phantom fix). "
    h += "<a href='?since=2026-05-26'>26/mai</a> &nbsp;|&nbsp; "
    h += "<a href='?since=2026-06-01'>01/jun</a> &nbsp;|&nbsp; "
    h += "<a href='javascript:location.reload()'>↻ Refresh</a></p>"

    h += "<div class='note'>⚠️ <b>Metodologia</b>: Stage 1 usa rec75 = token atingiu +75% do entry estimado "
    h += "(mc_bottom × 1.30 × 1.75 = mc_bottom × 2.28) em 60min via token_ticks. "
    h += "Stage 2 usa os bounce_signals reais. Critério de ação: delta ≥ 15pp + n ≥ 20 por grupo + padrão monotônico. "
    h += "Com n pequeno, tudo é exploratório — não grid search.</div>"

    try:
        conn = psycopg2.connect(db.DATABASE_URL)
        conn.autocommit = True
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

        # ── Pré-computa rec75 para todas as migrations com mc_bottom ───────────
        # rec75 = max(mc em token_ticks, 90s–60min) >= mc_bottom * 2.275
        # (equivale a: entrando em mc_bottom*1.30, TP em +75% da entrada)
        cur.execute("""
            WITH ticks_peak AS (
                SELECT
                    tt.mint,
                    MAX(tt.mc) AS max_mc_60
                FROM token_ticks tt
                JOIN migrations m ON m.mint = tt.mint
                WHERE m.ts_migration >= %(s)s::timestamptz
                  AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                  AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'
                GROUP BY tt.mint
            )
            SELECT
                m.mint,
                m.token_nome          AS symbol,
                m.ts_migration,
                m.mc_migration,
                m.mc_bottom,
                m.smart_wallets,
                m.renowned_wallets,
                m.sniper_wallets,
                m.rug_ratio,
                m.top10_holder_rate,
                m.rat_trader_rate,
                m.bundler_trader_amount_rate,
                m.is_wash_trading,
                m.bot_degen_rate,
                m.entrapment_ratio,
                m.cto_flag,
                m.has_social,
                m.creator_token_status,
                m.top70_sniper_hold_rate,
                m.total_fee_sol,
                m.liq_migration,
                tp.max_mc_60,
                CASE
                    WHEN m.mc_bottom > 0 AND tp.max_mc_60 IS NOT NULL
                    THEN (tp.max_mc_60 >= m.mc_bottom * 2.275)
                    ELSE NULL
                END AS rec75,
                -- pct_drop medido vs migração
                CASE WHEN m.mc_migration > 0
                    THEN (m.mc_migration - m.mc_bottom) / m.mc_migration
                    ELSE NULL
                END AS drop_from_mig
            FROM migrations m
            LEFT JOIN ticks_peak tp ON tp.mint = m.mint
            WHERE m.ts_migration >= %(s)s::timestamptz
            ORDER BY m.ts_migration DESC
        """, {"s": since_ts})
        all_mig = cur.fetchall()

        n_total = len(all_mig)
        n_with_bottom = sum(1 for r in all_mig if r["mc_bottom"] is not None)
        n_with_rec = sum(1 for r in all_mig if r["rec75"] is not None)
        n_rec75 = sum(1 for r in all_mig if r["rec75"] is True)
        baseline_rec75 = n_rec75 / n_with_rec if n_with_rec else 0

        try:
            d0 = _date.fromisoformat(since_ts)
            n_days = max(1, (_date.today() - d0).days)
        except Exception:
            n_days = 14

        # ── SEÇÃO 0: RESUMO DOS DADOS ──────────────────────────────────────────
        h += "<h2>0 · Resumo do Dataset</h2>"
        h += "<table><tr><th>Métrica</th><th>Valor</th><th>Nota</th></tr>"
        h += f"<tr><td>Período</td><td class='hi'>{n_days} dias</td><td class='dim'>Desde {since_ts}</td></tr>"
        h += f"<tr><td>Migrações no scanner</td><td>{n_total}</td><td class='dim'>{n_total/n_days:.1f}/dia</td></tr>"
        h += f"<tr><td>Com mc_bottom confirmado</td><td>{n_with_bottom}</td><td class='dim'>{100*n_with_bottom/max(n_total,1):.0f}% do total</td></tr>"
        h += f"<tr><td>Com token_ticks (rec75 computável)</td><td>{n_with_rec}</td><td class='dim'>{100*n_with_rec/max(n_total,1):.0f}% do total</td></tr>"
        h += f"<tr><td class='hi'>Baseline rec75 (sem filtro)</td><td class='hi'>{baseline_rec75*100:.0f}% ({n_rec75}/{n_with_rec})</td><td class='dim'>% que atingiu +75% do entry estimado</td></tr>"
        h += f"<tr><td>Bounce signals disparados</td><td>8</td><td class='dim'>Dados Stage 2 (n insuficiente para calibrar)</td></tr>"
        h += "</table>"

        h += "<div class='note'>📌 <b>Critério de ação</b>: só implementa filtro se delta rec75 ≥ 15pp "
        h += "E n ≥ 20 por grupo E padrão monotônico. Abaixo disso: exploratório apenas.</div>"

        # ── Helper: analisa uma feature contínua ──────────────────────────────
        def analyze_feature(label, rows, get_val, buckets, unit=""):
            """Retorna HTML de tabela com rec75 por bucket."""
            data = []
            for lo, hi, bucket_label in buckets:
                bucket = [r for r in rows
                          if r["rec75"] is not None
                          and get_val(r) is not None
                          and lo <= get_val(r) < hi]
                n_b = len(bucket)
                n_good = sum(1 for r in bucket if r["rec75"])
                wr = n_good / n_b if n_b else None
                data.append((bucket_label, n_b, n_good, wr))

            out = f"<h3>{label}</h3>"
            coverage = sum(1 for r in rows if get_val(r) is not None)
            out += f"<p class='dim'>Cobertura: {coverage}/{len(rows)} tokens com dado</p>"
            out += "<table><tr><th>Faixa</th><th>N tokens</th><th>rec75</th><th>vs baseline</th><th>Sinal</th></tr>"
            for blabel, n_b, n_good, wr in data:
                if wr is None:
                    out += f"<tr><td>{blabel}</td><td class='dim'>0</td><td>—</td><td>—</td><td>—</td></tr>"
                    continue
                delta = wr - baseline_rec75
                wr_color = "#3fb950" if delta > 0.10 else "#f85149" if delta < -0.10 else "#8b949e"
                actionable = n_b >= 20 and abs(delta) >= 0.15
                signal = "✅ acionável" if actionable else ("📊 tendência" if abs(delta) >= 0.10 else "— ruído")
                sig_color = "#3fb950" if actionable else ("#f0883e" if abs(delta) >= 0.10 else "#8b949e")
                out += (f"<tr><td>{blabel}</td><td>{n_b}</td>"
                        f"<td style='color:{wr_color}'><b>{wr*100:.0f}%</b></td>"
                        f"<td style='color:{wr_color}'>{delta*100:+.0f}pp</td>"
                        f"<td style='color:{sig_color}'>{signal}</td></tr>")
            out += "</table>"
            return out

        # ── SEÇÃO 1: FILTROS STAGE 1 — QUALIDADE DO TOKEN ─────────────────────
        h += "<h2>1 · Stage 1 — Filtros de Qualidade (pré-scanner)</h2>"
        h += "<p class='dim'>Rec75 = token atingiu +75% do entry estimado (mc_bottom × 2.28) em 60min. "
        h += f"Baseline: <b>{baseline_rec75*100:.0f}%</b> ({n_rec75}/{n_with_rec})</p>"

        # 1.1 smart_wallets
        h += analyze_feature(
            "Smart Wallets (smart_degen_count)",
            all_mig,
            lambda r: r["smart_wallets"],
            [(0, 1, "0"), (1, 2, "1"), (2, 3, "2"), (3, 4, "3"), (4, 6, "4-5"), (6, 999, "6+")]
        )

        # 1.2 top10_holder_rate
        h += analyze_feature(
            "Top 10 Holder Rate",
            all_mig,
            lambda r: r["top10_holder_rate"],
            [(0, 0.5, "0–50%"), (0.5, 0.65, "50–65%"), (0.65, 0.75, "65–75%"),
             (0.75, 0.85, "75–85%"), (0.85, 1.0, "85–100%")]
        )

        # 1.3 rat_trader_rate
        h += analyze_feature(
            "Rat Trader Rate",
            all_mig,
            lambda r: r["rat_trader_rate"],
            [(0, 0.05, "0–5%"), (0.05, 0.10, "5–10%"), (0.10, 0.15, "10–15%"),
             (0.15, 0.20, "15–20%"), (0.20, 1.0, "20%+")]
        )

        # 1.4 bundler_trader_amount_rate
        h += analyze_feature(
            "Bundler Rate",
            all_mig,
            lambda r: r["bundler_trader_amount_rate"],
            [(0, 0.05, "0–5%"), (0.05, 0.15, "5–15%"), (0.15, 0.30, "15–30%"),
             (0.30, 0.50, "30–50%"), (0.50, 1.0, "50%+")]
        )

        # 1.5 rug_ratio
        h += analyze_feature(
            "Rug Ratio (score GMGN)",
            all_mig,
            lambda r: r["rug_ratio"],
            [(0, 0.05, "0–5%"), (0.05, 0.15, "5–15%"), (0.15, 0.30, "15–30%"),
             (0.30, 0.50, "30–50%"), (0.50, 1.0, "50%+")]
        )

        # 1.6 bot_degen_rate
        h += analyze_feature(
            "Bot Degen Rate",
            all_mig,
            lambda r: r["bot_degen_rate"],
            [(0, 0.3, "0–30%"), (0.3, 0.5, "30–50%"), (0.5, 0.7, "50–70%"),
             (0.7, 0.9, "70–90%"), (0.9, 1.0, "90–100%")]
        )

        # 1.7 top70_sniper_hold_rate
        h += analyze_feature(
            "Top 70 Sniper Hold Rate",
            all_mig,
            lambda r: r["top70_sniper_hold_rate"],
            [(0, 0.10, "0–10%"), (0.10, 0.20, "10–20%"), (0.20, 0.35, "20–35%"),
             (0.35, 0.50, "35–50%"), (0.50, 1.0, "50%+")]
        )

        # 1.8 sniper_wallets count
        h += analyze_feature(
            "Sniper Wallets (count)",
            all_mig,
            lambda r: r["sniper_wallets"],
            [(0, 5, "0–4"), (5, 10, "5–9"), (10, 20, "10–19"),
             (20, 40, "20–39"), (40, 999, "40+")]
        )

        # 1.9 entrapment_ratio
        h += analyze_feature(
            "Entrapment Ratio",
            all_mig,
            lambda r: r["entrapment_ratio"],
            [(0, 0.1, "0–10%"), (0.1, 0.2, "10–20%"), (0.2, 0.4, "20–40%"),
             (0.4, 1.0, "40%+")]
        )

        # 1.10 total_fee_sol
        h += analyze_feature(
            "Total Fee (SOL) — proxy de volume real",
            all_mig,
            lambda r: r["total_fee_sol"],
            [(0, 1, "<1 SOL"), (1, 3, "1–3 SOL"), (3, 7, "3–7 SOL"),
             (7, 15, "7–15 SOL"), (15, 999, "15+ SOL")]
        )

        # 1.11 is_wash_trading (binário)
        h += "<h3>Is Wash Trading (binário)</h3>"
        for val, label in [(False, "Não wash"), (True, "Wash trading")]:
            grp = [r for r in all_mig if r["rec75"] is not None and r["is_wash_trading"] == val]
            n_g = len(grp)
            n_good = sum(1 for r in grp if r["rec75"])
            wr = n_good / n_g if n_g else None
            delta = (wr - baseline_rec75) if wr is not None else None
            h += (f"<p class='dim'>{label}: n={n_g}, rec75={f'{wr*100:.0f}%' if wr is not None else '—'} "
                  f"({f'{delta*100:+.0f}pp vs baseline' if delta is not None else ''})</p>")

        # 1.12 creator_token_status
        h += "<h3>Creator Token Status</h3>"
        for val in ["creator_hold", "creator_close", None]:
            grp = [r for r in all_mig if r["rec75"] is not None and r["creator_token_status"] == val]
            n_g = len(grp)
            n_good = sum(1 for r in grp if r["rec75"])
            wr = n_good / n_g if n_g else None
            delta = (wr - baseline_rec75) if wr is not None else None
            label = val or "NULL/desconhecido"
            h += (f"<p class='dim'>{label}: n={n_g}, rec75={f'{wr*100:.0f}%' if wr is not None else '—'} "
                  f"({f'{delta*100:+.0f}pp' if delta is not None else ''})</p>")

        # 1.13 cto_flag e has_social
        for fname, fkey in [("CTO Flag", "cto_flag"), ("Has Social", "has_social")]:
            h += f"<h3>{fname}</h3>"
            for val, label in [(True, "Sim"), (False, "Não")]:
                grp = [r for r in all_mig if r["rec75"] is not None and r[fkey] == val]
                n_g = len(grp)
                n_good = sum(1 for r in grp if r["rec75"])
                wr = n_good / n_g if n_g else None
                delta = (wr - baseline_rec75) if wr is not None else None
                h += (f"<p class='dim'>{label}: n={n_g}, rec75={f'{wr*100:.0f}%' if wr is not None else '—'} "
                      f"({f'{delta*100:+.0f}pp' if delta is not None else ''})</p>")

        # ── SEÇÃO 2: DISTRIBUIÇÃO DOS FILTROS ATUAIS ──────────────────────────
        h += "<h2>2 · Distribuição dos Filtros Atuais no Dataset</h2>"
        h += "<p class='dim'>Onde os 164 tokens caem em cada filtro. "
        h += "Filtros que bloqueiam >90% dos tokens têm impacto no volume de sinais.</p>"

        cur.execute("""
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN smart_wallets >= 3 THEN 1 ELSE 0 END) AS smart_gte3,
                SUM(CASE WHEN smart_wallets >= 2 THEN 1 ELSE 0 END) AS smart_gte2,
                SUM(CASE WHEN top10_holder_rate <= 0.80 THEN 1 ELSE 0 END) AS top10_ok,
                SUM(CASE WHEN rat_trader_rate <= 0.20 THEN 1 ELSE 0 END) AS rat_ok,
                SUM(CASE WHEN bundler_trader_amount_rate <= 0.60 THEN 1 ELSE 0 END) AS bundler_ok,
                SUM(CASE WHEN rug_ratio <= 0.50 THEN 1 ELSE 0 END) AS rug_ok,
                SUM(CASE WHEN bot_degen_rate <= 0.80 THEN 1 ELSE 0 END) AS bot_ok,
                SUM(CASE WHEN (is_wash_trading IS NULL OR is_wash_trading = FALSE) THEN 1 ELSE 0 END) AS wash_ok,
                SUM(CASE WHEN liq_migration >= 10000 THEN 1 ELSE 0 END) AS liq_ok,
                SUM(CASE WHEN total_fee_sol >= 1.0 THEN 1 ELSE 0 END) AS fee_ok,
                -- cobertura de dados
                SUM(CASE WHEN smart_wallets IS NOT NULL THEN 1 ELSE 0 END) AS cov_smart,
                SUM(CASE WHEN top10_holder_rate IS NOT NULL THEN 1 ELSE 0 END) AS cov_top10,
                SUM(CASE WHEN rat_trader_rate IS NOT NULL THEN 1 ELSE 0 END) AS cov_rat,
                SUM(CASE WHEN bundler_trader_amount_rate IS NOT NULL THEN 1 ELSE 0 END) AS cov_bundler,
                SUM(CASE WHEN bot_degen_rate IS NOT NULL THEN 1 ELSE 0 END) AS cov_bot
            FROM migrations
            WHERE ts_migration >= %(s)s::timestamptz
        """, {"s": since_ts})
        dist = cur.fetchone()
        tot = dist["total"] or 1

        h += "<table><tr><th>Filtro (threshold atual)</th><th>Passam</th><th>%</th><th>Cobertura</th><th>Impacto vol.</th></tr>"
        filter_rows = [
            ("smart_wallets ≥ 3", dist["smart_gte3"], dist["cov_smart"]),
            ("smart_wallets ≥ 2", dist["smart_gte2"], dist["cov_smart"]),
            ("top10_holder_rate ≤ 80%", dist["top10_ok"], dist["cov_top10"]),
            ("rat_trader_rate ≤ 20%", dist["rat_ok"], dist["cov_rat"]),
            ("bundler_rate ≤ 60%", dist["bundler_ok"], dist["cov_bundler"]),
            ("rug_ratio ≤ 50%", dist["rug_ok"], dist["cov_smart"]),  # same coverage approx
            ("bot_degen_rate ≤ 80%", dist["bot_ok"], dist["cov_bot"]),
            ("is_wash_trading = FALSE", dist["wash_ok"], tot),
            ("liq_migration ≥ $10k", dist["liq_ok"], tot),
            ("total_fee_sol ≥ 1.0", dist["fee_ok"], tot),
        ]
        for fname, n_pass, n_cov in filter_rows:
            n_pass = n_pass or 0
            pct_pass = 100 * n_pass / tot
            impact = "🔴 alto" if pct_pass < 40 else "🟡 médio" if pct_pass < 70 else "🟢 baixo"
            pct_color = "#f85149" if pct_pass < 40 else "#f0883e" if pct_pass < 70 else "#3fb950"
            h += (f"<tr><td class='hi'>{fname}</td>"
                  f"<td>{n_pass}/{tot}</td>"
                  f"<td style='color:{pct_color}'>{pct_pass:.0f}%</td>"
                  f"<td class='dim'>{n_cov}/{tot}</td>"
                  f"<td>{impact}</td></tr>")
        h += "</table>"

        # ── SEÇÃO 3: STAGE 2 — FILTROS DE BOUNCE ──────────────────────────────
        h += "<h2>3 · Stage 2 — Filtros de Bounce (sinal de entrada)</h2>"
        h += "<div class='note'>⚠️ <b>n=8 bounce_signals</b> — insuficiente para calibrar estatisticamente. "
        h += "Apresentado apenas como referência descritiva. Não alterar thresholds de Stage 2 antes de n≥30 GMGN.</div>"

        cur.execute("""
            SELECT
                bs.symbol, bs.bounce_pct, bs.drop_from_mig, bs.elapsed_sec,
                bs.pool_quote_at_signal, bs.net_sol_flow, bs.rise_events,
                bs.absorption_events, bs.buy_concentration,
                -- simula rec75 via token_ticks pós-sinal
                (SELECT MAX(tt.mc) FROM token_ticks tt
                 WHERE tt.mint = bs.mint
                   AND tt.tick_ts > bs.ts_signal
                   AND tt.tick_ts < bs.ts_signal + INTERVAL '20 minutes'
                ) AS max_mc_20min,
                bs.mc_at_signal, bs.mc_min,
                t.status AS trade_status, t.pnl_pct_real
            FROM bounce_signals bs
            LEFT JOIN trades t ON t.mint = bs.mint
                AND t.ts_signal >= bs.ts_signal - INTERVAL '30 seconds'
                AND t.ts_signal <= bs.ts_signal + INTERVAL '30 seconds'
            WHERE bs.ts_signal >= %(s)s::timestamptz
            ORDER BY bs.ts_signal DESC
        """, {"s": since_ts})
        bs_rows = cur.fetchall()

        h += "<h3>Bounce Signals — Descritivo Completo</h3>"
        h += ("<table><tr><th>Símbolo</th><th>bounce%</th><th>drop%</th>"
              "<th>elapsed</th><th>pool SOL</th><th>net_flow</th>"
              "<th>rise_ev</th><th>abs_ev</th><th>buy_conc</th>"
              "<th>max 20min</th><th>rec75?</th><th>trade</th></tr>")
        for r in bs_rows:
            bp = (r["bounce_pct"] or 0) * 100
            drop = (r["drop_from_mig"] or 0) * 100
            el = r["elapsed_sec"] or 0
            pool = r["pool_quote_at_signal"]
            net = r["net_sol_flow"]
            mc_sig = r["mc_at_signal"] or 0
            max20 = r["max_mc_20min"]
            rec = (max20 >= mc_sig * 1.75) if (max20 and mc_sig) else None
            rec_s = "✅ sim" if rec is True else ("❌ não" if rec is False else "—")
            rec_col = "#3fb950" if rec else ("#f85149" if rec is False else "#8b949e")
            trade_s = "—"
            if r["trade_status"]:
                pnl = r["pnl_pct_real"]
                pnl_s = "{:+.0f}%".format(pnl * 100) if pnl is not None else ""
                t_col = "#3fb950" if r["trade_status"] in ("tp", "trailing_active") else "#f85149" if r["trade_status"] == "sl" else "#8b949e"
                trade_s = f"<span style='color:{t_col}'>{r['trade_status']} {pnl_s}</span>"
            h += (f"<tr><td class='hi'>{r['symbol'] or '?'}</td>"
                  f"<td class='warn'>{bp:.0f}%</td>"
                  f"<td class='dim'>-{drop:.0f}%</td>"
                  f"<td class='dim'>{el//60}m{el%60}s</td>"
                  f"<td class='dim'>{'{:.1f}'.format(pool) if pool else '—'}</td>"
                  f"<td class='dim'>{'{:+.2f}'.format(net) if net is not None else '—'}</td>"
                  f"<td class='dim'>{r['rise_events'] or '—'}</td>"
                  f"<td class='dim'>{r['absorption_events'] or '—'}</td>"
                  f"<td class='dim'>{'{:.2f}'.format(r['buy_concentration']) if r['buy_concentration'] else '—'}</td>"
                  f"<td class='dim'>${'{:.0f}'.format(max20/1000)+'k' if max20 else '—'}</td>"
                  f"<td style='color:{rec_col}'>{rec_s}</td>"
                  f"<td>{trade_s}</td></tr>")
        h += "</table>"

        # ── SEÇÃO 4: FILTROS COMBINADOS — IMPACTO EM VOLUME ───────────────────
        h += "<h2>4 · Combinações de Filtros — Quantos Tokens Sobram</h2>"
        h += "<p class='dim'>Simula quantos dos 164 tokens passariam com diferentes combinações Stage 1. "
        h += "Volume × qualidade são inversamente proporcionais — ver onde está o equilíbrio.</p>"

        combos = [
            ("Nenhum filtro extra", "1=1"),
            ("smart ≥ 2", "smart_wallets >= 2"),
            ("smart ≥ 3", "smart_wallets >= 3"),
            ("rat ≤ 20%", "rat_trader_rate <= 0.20"),
            ("bundler ≤ 30%", "bundler_trader_amount_rate <= 0.30"),
            ("top10 ≤ 75%", "top10_holder_rate <= 0.75"),
            ("smart≥2 + rat≤20%", "smart_wallets >= 2 AND rat_trader_rate <= 0.20"),
            ("smart≥2 + rat≤20% + bundler≤30%", "smart_wallets >= 2 AND rat_trader_rate <= 0.20 AND bundler_trader_amount_rate <= 0.30"),
            ("smart≥3 + rat≤20%", "smart_wallets >= 3 AND rat_trader_rate <= 0.20"),
            ("smart≥3 + rat≤20% + top10≤75%", "smart_wallets >= 3 AND rat_trader_rate <= 0.20 AND top10_holder_rate <= 0.75"),
        ]
        h += "<table><tr><th>Combinação</th><th>N tokens pass</th><th>%</th><th>Est./dia</th></tr>"
        for label, cond in combos:
            cur.execute(f"""
                SELECT COUNT(*) AS n FROM migrations
                WHERE ts_migration >= %(s)s::timestamptz AND ({cond})
            """, {"s": since_ts})
            n_pass = cur.fetchone()["n"] or 0
            pct = 100 * n_pass / tot
            pct_col = "#f85149" if pct < 20 else "#f0883e" if pct < 50 else "#3fb950"
            h += (f"<tr><td class='hi'>{label}</td><td>{n_pass}</td>"
                  f"<td style='color:{pct_col}'>{pct:.0f}%</td>"
                  f"<td class='dim'>{n_pass/n_days:.1f}</td></tr>")
        h += "</table>"

        # ── SEÇÃO 5: RECOMENDAÇÃO EXECUTIVA ───────────────────────────────────
        h += "<h2>5 · Recomendação Executiva</h2>"
        h += "<div class='note'>"
        h += "<b>Stage 1 (filtros de qualidade):</b><br>"
        h += "• Qualquer filtro com delta &lt; 15pp ou n &lt; 20 = exploratório apenas. Não implementar.<br>"
        h += "• Foque em: smart_wallets (único com evidência live) e is_wash_trading (binário, baixo custo).<br>"
        h += "• Demais filtros: manter thresholds atuais sem ajuste até n ≥ 200 clean.<br>"
        h += "<br>"
        h += "<b>Stage 2 (bounce trigger):</b><br>"
        h += "• n=8 sinais / 4 outcomes = insuficiente para qualquer calibração. Intocável.<br>"
        h += f"• Com o anti-decline fix deployado hoje, espera-se 6–8 sinais/dia. "
        h += "Acumule 30+ outcomes GMGN antes de ajustar BOUNCE_MIN_PCT, BOUNCE_MAX_PCT ou MIN_POOL_SOL.<br>"
        h += "<br>"
        h += "<b>Próximo checkpoint:</b><br>"
        h += "• Após 30 trades GMGN com dados limpos: reabrir esta análise.<br>"
        h += "• Após 200 migrações limpas: análise Stage 1 com poder estatístico adequado."
        h += "</div>"

        cur.close()
        conn.close()

    except Exception as e:
        import traceback
        h += f"<pre style='color:#f85149'>ERRO: {e}\n{traceback.format_exc()}</pre>"

    h += "</body></html>"
    return h


@app.route("/analise/ticks-features")
def analise_ticks_features():  # noqa: C901
    """
    Calibração Stage 2 derivada exclusivamente de token_ticks (pós-2026-05-26).

    Para cada token que entrou no HotMonitor, computa diretamente dos ticks:
      - mc_bottom   = min(mc) na janela 90s–60min
      - elapsed_min = minutos entre ts_migration e o tick de menor MC
      - drop_pct    = (mc_migration - mc_bottom) / mc_migration
      - rec75       = max(mc após fundo) >= mc_bottom × 2.275
                      (equivale a: entry em +30% do fundo, TP em +75% do entry)

    Não depende de bounce_signals (n=8) nem de migrations.mc_bottom.
    Dataset limpo: 110 tokens com ticks pós phantom fix.
    """
    import psycopg2.extras
    from datetime import date as _date

    since_ts = request.args.get("since", "2026-05-26") or "2026-05-26"

    CSS = (
        "<style>"
        "body{background:#0d1117;color:#e6edf3;font:12px/1.6 monospace;padding:20px}"
        "h2{color:#58a6ff;margin-top:28px;border-bottom:1px solid #30363d;padding-bottom:6px}"
        "h3{color:#79c0ff;margin-top:18px}"
        "table{border-collapse:collapse;width:100%;margin-bottom:14px}"
        "th{background:#161b22;padding:6px 10px;text-align:left;font-size:11px;"
        "color:#8b949e;border-bottom:2px solid #30363d}"
        "td{padding:4px 10px;border-bottom:1px solid #21262d;font-size:11px}"
        ".good{color:#3fb950}.warn{color:#f0883e}.bad{color:#f85149}"
        ".dim{color:#8b949e}.hi{color:#e6edf3;font-weight:bold}"
        ".note{background:#1a1f2e;padding:8px 12px;border-left:3px solid #388bfd;"
        "margin:8px 0;font-size:11px}"
        "a{color:#58a6ff}"
        "</style>"
    )

    h = "<html><head><meta charset='utf-8'>" + CSS + "</head><body>"
    h += "<h2>📊 Token Ticks Features — Stage 2 Calibração</h2>"
    h += "<p class='dim'>Período desde <b>{}</b> · ".format(since_ts)
    h += "<a href='?since=2026-05-26'>26/mai</a> | "
    h += "<a href='?since=2026-06-01'>01/jun</a> | "
    h += "<a href='javascript:location.reload()'>↻</a></p>"
    h += "<div class='note'>Fonte: token_ticks 90s–60min. Outcome: rec75 = max_mc_pós_fundo ≥ mc_bottom × 2.275. "
    h += "Critério de ação: delta ≥ 15pp + n ≥ 20 por grupo + padrão monotônico.</div>"

    try:
        conn = psycopg2.connect(db.DATABASE_URL)
        conn.autocommit = True
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

        # ── Core query: bottom + rec75 calculados 100% dos token_ticks ────────
        cur.execute("""
            WITH tick_window AS (
                SELECT
                    tt.mint,
                    tt.mc,
                    tt.tick_ts,
                    EXTRACT(EPOCH FROM (tt.tick_ts - m.ts_migration)) AS elapsed_sec,
                    m.mc_migration,
                    m.ts_migration,
                    m.smart_wallets,
                    m.renowned_wallets,
                    m.sniper_wallets,
                    m.top10_holder_rate,
                    m.rat_trader_rate,
                    m.bundler_trader_amount_rate,
                    m.bot_degen_rate,
                    m.total_fee_sol,
                    m.liq_migration,
                    m.cto_flag,
                    m.creator_token_status
                FROM token_ticks tt
                JOIN migrations m ON m.mint = tt.mint
                WHERE m.ts_migration >= %(s)s::timestamptz
                  AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                  AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'
            ),
            bottom_per_mint AS (
                SELECT DISTINCT ON (mint)
                    mint, mc AS mc_bottom, elapsed_sec AS elapsed_to_bottom_sec,
                    mc_migration, smart_wallets, renowned_wallets, sniper_wallets,
                    top10_holder_rate, rat_trader_rate, bundler_trader_amount_rate,
                    bot_degen_rate, total_fee_sol, liq_migration, cto_flag, creator_token_status
                FROM tick_window
                ORDER BY mint, mc ASC, elapsed_sec ASC
            ),
            max_after_bottom AS (
                SELECT tw.mint, MAX(tw.mc) AS mc_max_after
                FROM tick_window tw
                JOIN bottom_per_mint bp ON bp.mint = tw.mint
                WHERE tw.elapsed_sec > bp.elapsed_to_bottom_sec
                GROUP BY tw.mint
            )
            SELECT
                bp.mint,
                bp.mc_bottom,
                bp.elapsed_to_bottom_sec / 60.0          AS elapsed_min,
                bp.mc_migration,
                CASE WHEN bp.mc_migration > 0
                    THEN (bp.mc_migration - bp.mc_bottom) / bp.mc_migration
                    ELSE NULL END                         AS drop_pct,
                mab.mc_max_after,
                CASE WHEN mab.mc_max_after IS NOT NULL AND bp.mc_bottom > 0
                    THEN mab.mc_max_after >= bp.mc_bottom * 2.275
                    ELSE NULL END                         AS rec75,
                bp.smart_wallets,
                bp.renowned_wallets,
                bp.sniper_wallets,
                bp.top10_holder_rate,
                bp.rat_trader_rate,
                bp.bundler_trader_amount_rate,
                bp.bot_degen_rate,
                bp.total_fee_sol,
                bp.liq_migration,
                bp.cto_flag,
                bp.creator_token_status
            FROM bottom_per_mint bp
            LEFT JOIN max_after_bottom mab ON mab.mint = bp.mint
            WHERE bp.mc_bottom IS NOT NULL AND bp.mc_bottom > 0
            ORDER BY bp.mint
        """, {"s": since_ts})
        rows = cur.fetchall()

        n_total   = len(rows)
        n_rec     = sum(1 for r in rows if r["rec75"] is not None)
        n_rec75   = sum(1 for r in rows if r["rec75"] is True)
        baseline  = n_rec75 / n_rec if n_rec else 0

        try:
            d0 = _date.fromisoformat(since_ts)
            n_days = max(1, (_date.today() - d0).days)
        except Exception:
            n_days = 15

        h += "<h2>0 · Resumo</h2>"
        h += "<table><tr><th>Métrica</th><th>Valor</th><th>Nota</th></tr>"
        h += "<tr><td>Tokens com ticks (pós 90s)</td><td class='hi'>{}</td><td class='dim'>{:.1f}/dia</td></tr>".format(n_total, n_total / n_days)
        h += "<tr><td>Com rec75 computável</td><td>{}</td><td class='dim'>{:.0f}% têm ticks pós-fundo</td></tr>".format(n_rec, 100 * n_rec / max(n_total, 1))
        h += "<tr><td class='hi'>Baseline rec75</td><td class='hi'>{:.0f}% ({}/{})</td><td class='dim'>% que atingiu mc_bottom × 2.275 após o fundo</td></tr>".format(baseline * 100, n_rec75, n_rec)
        h += "</table>"

        # ── Helper analyze_buckets ─────────────────────────────────────────────
        def bucket_table(label, get_val, buckets, note=""):
            cov = sum(1 for r in rows if get_val(r) is not None)
            out = "<h3>{}</h3>".format(label)
            if note:
                out += "<p class='dim'>{}</p>".format(note)
            out += "<p class='dim'>Cobertura: {}/{} tokens</p>".format(cov, n_total)
            out += ("<table><tr><th>Faixa</th><th>N</th><th>rec75</th>"
                    "<th>vs baseline</th><th>Sinal</th></tr>")
            for lo, hi, blabel in buckets:
                grp = [r for r in rows
                       if r["rec75"] is not None
                       and get_val(r) is not None
                       and lo <= get_val(r) < hi]
                n_g  = len(grp)
                n_tp = sum(1 for r in grp if r["rec75"])
                wr   = n_tp / n_g if n_g else None
                if wr is None:
                    out += "<tr><td>{}</td><td class='dim'>0</td><td>—</td><td>—</td><td>—</td></tr>".format(blabel)
                    continue
                delta = wr - baseline
                col   = "#3fb950" if delta > 0.10 else "#f85149" if delta < -0.10 else "#8b949e"
                act   = n_g >= 20 and abs(delta) >= 0.15
                sig   = "✅ acionável" if act else ("📊 tendência" if abs(delta) >= 0.08 else "— ruído")
                sc    = "#3fb950" if act else ("#f0883e" if abs(delta) >= 0.08 else "#8b949e")
                out += ("<tr><td>{}</td><td>{}</td>"
                        "<td style='color:{}'><b>{:.0f}%</b></td>"
                        "<td style='color:{}'>{:+.0f}pp</td>"
                        "<td style='color:{}'>{}</td></tr>").format(
                    blabel, n_g, col, wr * 100, col, delta * 100, sc, sig)
            out += "</table>"
            return out

        # ════════════════════════════════════════════════════════════════════════
        # STAGE 2 — Features temporais / estruturais (calculadas dos ticks)
        # ════════════════════════════════════════════════════════════════════════
        h += "<h2>1 · Stage 2 — Features Estruturais (derivadas de token_ticks)</h2>"
        h += "<p class='dim'>Estas features descrevem O DUMP em si, não a qualidade do token. "
        h += "Cada valor é computado diretamente dos ticks — sem dependência de bounce_signals.</p>"

        # 1a. Tempo até o fundo (elapsed_min)
        h += bucket_table(
            "Tempo até o Fundo (elapsed_min desde migração)",
            lambda r: r["elapsed_min"],
            [(0, 3,  "0–3 min"),
             (3, 5,  "3–5 min"),
             (5, 10, "5–10 min"),
             (10, 20, "10–20 min"),
             (20, 60, "20–60 min")],
            note="H10 hipótese: fundo rápido (< 10min) → melhor recovery. "
                 "Dados anteriores confirmaram +22pp mas com mc_bottom corrompido."
        )

        # 1b. Profundidade do dump (drop_pct)
        h += bucket_table(
            "Profundidade do Dump (drop_pct vs mc_migration)",
            lambda r: r["drop_pct"],
            [(0,   0.20, "0–20% drop"),
             (0.20, 0.35, "20–35% drop"),
             (0.35, 0.50, "35–50% drop"),
             (0.50, 0.65, "50–65% drop"),
             (0.65, 0.80, "65–80% drop"),
             (0.80, 1.00, "80%+ drop")],
            note="Drop profundo = mais upside potencial, mas também mais sellers pendentes."
        )

        # 1c. Tamanho da migração (mc_migration)
        h += bucket_table(
            "Tamanho na Migração (mc_migration USD)",
            lambda r: r["mc_migration"],
            [(0,      10000, "< $10k"),
             (10000,  20000, "$10k–$20k"),
             (20000,  35000, "$20k–$35k"),
             (35000,  55000, "$35k–$55k"),
             (55000,  85000, "$55k–$85k"),
             (85000, 999999, "> $85k")],
            note="Tokens maiores têm mais liquidez — menos slippage mas mais capital para sair."
        )

        # 1d. Liquidez na migração
        h += bucket_table(
            "Liquidez na Migração (liq_migration USD)",
            lambda r: r["liq_migration"],
            [(0,      5000, "< $5k"),
             (5000,  15000, "$5k–$15k"),
             (15000, 25000, "$15k–$25k"),
             (25000, 40000, "$25k–$40k"),
             (40000, 999999, "> $40k")],
        )

        # 1e. Fee total (proxy de volume real)
        h += bucket_table(
            "Total Fee SOL (proxy de volume real)",
            lambda r: r["total_fee_sol"],
            [(0, 1, "< 1 SOL"),
             (1, 3, "1–3 SOL"),
             (3, 7, "3–7 SOL"),
             (7, 15, "7–15 SOL"),
             (15, 999, "15+ SOL")],
        )

        # ════════════════════════════════════════════════════════════════════════
        # STAGE 1 — Qualidade do token (via migrations, mesmo dataset)
        # ════════════════════════════════════════════════════════════════════════
        h += "<h2>2 · Stage 1 — Qualidade do Token (via migrations)</h2>"
        h += "<p class='dim'>Mesmos tokens, features de qualidade do scanner. "
        h += "Baseline: <b>{:.0f}%</b> ({}/{})</p>".format(baseline * 100, n_rec75, n_rec)

        h += bucket_table(
            "Smart Wallets",
            lambda r: r["smart_wallets"],
            [(0, 1, "0"), (1, 2, "1"), (2, 3, "2"), (3, 4, "3"),
             (4, 6, "4–5"), (6, 999, "6+")],
        )

        h += bucket_table(
            "Renowned Wallets (KOLs)",
            lambda r: r["renowned_wallets"],
            [(0, 1, "0"), (1, 2, "1"), (2, 4, "2–3"), (4, 999, "4+")],
        )

        h += bucket_table(
            "Sniper Wallets",
            lambda r: r["sniper_wallets"],
            [(0, 5, "0–4"), (5, 10, "5–9"), (10, 20, "10–19"),
             (20, 40, "20–39"), (40, 999, "40+")],
        )

        h += bucket_table(
            "Rat Trader Rate",
            lambda r: r["rat_trader_rate"],
            [(0, 0.02, "0–2%"), (0.02, 0.05, "2–5%"), (0.05, 0.10, "5–10%"),
             (0.10, 0.20, "10–20%"), (0.20, 1.0, "20%+")],
        )

        h += bucket_table(
            "Bundler Rate",
            lambda r: r["bundler_trader_amount_rate"],
            [(0, 0.10, "0–10%"), (0.10, 0.25, "10–25%"), (0.25, 0.40, "25–40%"),
             (0.40, 0.55, "40–55%"), (0.55, 1.0, "55%+")],
        )

        h += bucket_table(
            "Bot Degen Rate",
            lambda r: r["bot_degen_rate"],
            [(0, 0.30, "0–30%"), (0.30, 0.50, "30–50%"), (0.50, 0.70, "50–70%"),
             (0.70, 1.0, "70%+")],
        )

        # ── Binários ──────────────────────────────────────────────────────────
        h += "<h2>3 · Features Binárias</h2>"
        for fname, fkey in [("CTO Flag", "cto_flag"),
                             ("Creator Hold", "creator_token_status")]:
            h += "<h3>{}</h3>".format(fname)
            if fkey == "creator_token_status":
                pairs = [("creator_hold", "creator_hold"), ("creator_close", "creator_close")]
            else:
                pairs = [(True, "Sim"), (False, "Não")]
            for val, label in pairs:
                grp  = [r for r in rows if r["rec75"] is not None and r[fkey] == val]
                n_g  = len(grp)
                n_tp = sum(1 for r in grp if r["rec75"])
                wr   = n_tp / n_g if n_g else None
                delta = (wr - baseline) if wr is not None else None
                col  = "#3fb950" if (delta or 0) > 0.10 else "#f85149" if (delta or 0) < -0.10 else "#8b949e"
                h += "<p class='dim'>{}: n={}, rec75={} ({}</p>".format(
                    label, n_g,
                    "{:.0f}%".format(wr * 100) if wr is not None else "—",
                    "<span style='color:{}'>{:+.0f}pp</span>)".format(col, (delta or 0) * 100)
                )

        # ── Grid 2D: elapsed × drop ────────────────────────────────────────────
        h += "<h2>4 · Grid 2D — Elapsed × Drop (zona de entrada ideal)</h2>"
        h += "<p class='dim'>Rec75 por combinação de tempo até fundo + profundidade do dump.</p>"
        elapsed_buckets = [(0, 5, "0–5m"), (5, 10, "5–10m"), (10, 20, "10–20m"), (20, 60, "20m+")]
        drop_buckets    = [(0, 0.35, "<35%"), (0.35, 0.55, "35–55%"), (0.55, 0.75, "55–75%"), (0.75, 1.0, "75%+")]

        h += "<table><tr><th>Elapsed \\ Drop</th>"
        for _, _, dl in drop_buckets:
            h += "<th>{}</th>".format(dl)
        h += "</tr>"
        for el_lo, el_hi, el_label in elapsed_buckets:
            h += "<tr><td class='hi'>{}</td>".format(el_label)
            for dr_lo, dr_hi, _ in drop_buckets:
                cell = [r for r in rows
                        if r["rec75"] is not None
                        and r["elapsed_min"] is not None and el_lo <= r["elapsed_min"] < el_hi
                        and r["drop_pct"] is not None and dr_lo <= r["drop_pct"] < dr_hi]
                n_c  = len(cell)
                n_tp = sum(1 for r in cell if r["rec75"])
                wr   = n_tp / n_c if n_c else None
                if wr is None:
                    h += "<td class='dim'>—</td>"
                else:
                    delta = wr - baseline
                    col   = "#3fb950" if delta > 0.10 else "#f85149" if delta < -0.10 else "#8b949e"
                    h += "<td style='color:{}'><b>{:.0f}%</b><br><span class='dim'>n={}</span></td>".format(col, wr * 100, n_c)
            h += "</tr>"
        h += "</table>"

        # ── Token list (debug) ─────────────────────────────────────────────────
        h += "<h2>5 · Lista Completa</h2>"
        h += "<p class='dim'>Todos os {} tokens com ticks. Verde = rec75 ✅ / Vermelho = ❌</p>".format(n_total)
        h += ("<table><tr><th>Mint</th><th>mc_mig</th><th>mc_bottom</th>"
              "<th>drop%</th><th>elapsed</th><th>smart</th><th>rat%</th><th>bundler%</th><th>rec75</th></tr>")
        for r in sorted(rows, key=lambda x: (x["rec75"] is not True, x["elapsed_min"] or 0)):
            rec_col = "#3fb950" if r["rec75"] else ("#f85149" if r["rec75"] is False else "#8b949e")
            rec_s   = "✅" if r["rec75"] else ("❌" if r["rec75"] is False else "—")
            drop_s  = "{:.0f}%".format((r["drop_pct"] or 0) * 100)
            el_s    = "{:.1f}m".format(r["elapsed_min"]) if r["elapsed_min"] is not None else "—"
            h += ("<tr style='color:{}'><td class='dim'>{}</td>"
                  "<td>${:.0f}k</td><td>${:.0f}k</td><td>{}</td><td>{}</td>"
                  "<td>{}</td><td>{}</td><td>{}</td><td><b>{}</b></td></tr>").format(
                rec_col,
                r["mint"][:8],
                (r["mc_migration"] or 0) / 1000,
                (r["mc_bottom"] or 0) / 1000,
                drop_s, el_s,
                r["smart_wallets"] or "—",
                "{:.0f}%".format((r["rat_trader_rate"] or 0) * 100),
                "{:.0f}%".format((r["bundler_trader_amount_rate"] or 0) * 100),
                rec_s,
            )
        h += "</table>"

        cur.close()
        conn.close()

    except Exception as e:
        import traceback
        h += "<pre style='color:#f85149'>ERRO: {}\n{}</pre>".format(e, traceback.format_exc())

    h += "</body></html>"
    return h


@app.route("/analise/filter-impact")
def analise_filter_impact():  # noqa: C901
    """
    Para cada filtro ativo, mostra:
      - N tokens bloqueados vs N que passam
      - rec75 do grupo bloqueado vs grupo que passa
      - Se bloqueado tem rec75 MAIOR = filtro está errado (corta os bons)

    Dataset: token_ticks pós-2026-05-26 (dados limpos).
    Outcome: rec75 = max_mc_após_fundo >= mc_bottom_ticks × 2.275
    """
    import psycopg2.extras
    from datetime import date as _date

    since_ts = request.args.get("since", "2026-05-26") or "2026-05-26"

    CSS = (
        "<style>"
        "body{background:#0d1117;color:#e6edf3;font:12px/1.6 monospace;padding:20px}"
        "h2{color:#58a6ff;margin-top:28px;border-bottom:1px solid #30363d;padding-bottom:6px}"
        "h3{color:#79c0ff;margin-top:20px}"
        "table{border-collapse:collapse;width:100%;margin-bottom:10px}"
        "th{background:#161b22;padding:6px 10px;text-align:left;font-size:11px;"
        "color:#8b949e;border-bottom:2px solid #30363d}"
        "td{padding:5px 10px;border-bottom:1px solid #21262d;font-size:12px}"
        ".good{color:#3fb950}.warn{color:#f0883e}.bad{color:#f85149}"
        ".dim{color:#8b949e}.hi{color:#e6edf3;font-weight:bold}"
        ".note{background:#1a1f2e;padding:8px 12px;border-left:3px solid #388bfd;margin:8px 0;font-size:11px}"
        ".alert{background:#2d1b1b;padding:8px 12px;border-left:3px solid #f85149;margin:8px 0;font-size:11px}"
        "a{color:#58a6ff}"
        "</style>"
    )
    h = "<html><head><meta charset='utf-8'>" + CSS + "</head><body>"
    h += "<h2>🔬 Filter Impact — O que cada filtro bloqueia</h2>"
    h += "<p class='dim'>Período desde <b>{}</b> · ".format(since_ts)
    h += "<a href='?since=2026-05-26'>26/mai</a> | "
    h += "<a href='?since=2026-06-01'>01/jun</a> | "
    h += "<a href='javascript:location.reload()'>↻</a></p>"
    h += "<div class='note'>Lógica: se o grupo BLOQUEADO tem rec75 maior que o grupo que PASSA → "
    h += "o filtro está cortando os tokens bons. "
    h += "Rec75 = max(mc após fundo) ≥ mc_bottom × 2.275 em 60min de token_ticks.</div>"

    try:
        conn = psycopg2.connect(db.DATABASE_URL)
        conn.autocommit = True
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

        # ── Core: mesma query do ticks-features ───────────────────────────────
        cur.execute("""
            WITH tick_window AS (
                SELECT
                    tt.mint, tt.mc, tt.tick_ts,
                    EXTRACT(EPOCH FROM (tt.tick_ts - m.ts_migration)) AS elapsed_sec,
                    m.mc_migration, m.ts_migration, m.total_fee_sol, m.liq_migration
                FROM token_ticks tt
                JOIN migrations m ON m.mint = tt.mint
                WHERE m.ts_migration >= %s::timestamptz
                  AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                  AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'
            ),
            bottom_per_mint AS (
                SELECT DISTINCT ON (mint)
                    mint, mc AS mc_bottom, elapsed_sec AS elapsed_to_bottom,
                    mc_migration
                FROM tick_window
                ORDER BY mint, mc ASC, elapsed_sec ASC
            ),
            time_to_30pct AS (
                SELECT DISTINCT ON (tw.mint)
                    tw.mint,
                    tw.elapsed_sec AS elapsed_at_bounce30,
                    bp.elapsed_to_bottom AS elapsed_to_bottom,
                    (tw.elapsed_sec - bp.elapsed_to_bottom) AS secs_bottom_to_bounce30,
                    (tw.mc - bp.mc_bottom) / bp.mc_bottom AS bounce_pct_at_signal
                FROM tick_window tw
                JOIN bottom_per_mint bp ON bp.mint = tw.mint
                WHERE tw.elapsed_sec > bp.elapsed_to_bottom
                  AND bp.mc_bottom > 0
                  AND (tw.mc - bp.mc_bottom) / bp.mc_bottom >= 0.30
                ORDER BY tw.mint, tw.elapsed_sec ASC
            ),
            max_after_bottom AS (
                SELECT tw.mint, MAX(tw.mc) AS mc_max_after
                FROM tick_window tw
                JOIN bottom_per_mint bp ON bp.mint = tw.mint
                WHERE tw.elapsed_sec > bp.elapsed_to_bottom
                GROUP BY tw.mint
            )
            SELECT
                bp.mint,
                bp.mc_bottom,
                bp.elapsed_to_bottom,
                bp.mc_migration,
                CASE WHEN bp.mc_migration > 0
                    THEN (bp.mc_migration - bp.mc_bottom) / bp.mc_migration
                    ELSE NULL END AS drop_pct,
                mab.mc_max_after,
                CASE WHEN mab.mc_max_after IS NOT NULL AND bp.mc_bottom > 0
                    THEN mab.mc_max_after >= bp.mc_bottom * 2.275
                    ELSE NULL END AS rec75,
                t30.elapsed_at_bounce30,
                t30.secs_bottom_to_bounce30,
                t30.bounce_pct_at_signal
            FROM bottom_per_mint bp
            LEFT JOIN max_after_bottom mab ON mab.mint = bp.mint
            LEFT JOIN time_to_30pct t30 ON t30.mint = bp.mint
            WHERE bp.mc_bottom IS NOT NULL AND bp.mc_bottom > 0
        """, (since_ts,))
        rows = cur.fetchall()

        n_total  = len(rows)
        n_rec    = sum(1 for r in rows if r["rec75"] is not None)
        n_rec75  = sum(1 for r in rows if r["rec75"] is True)
        baseline = n_rec75 / n_rec if n_rec else 0

        try:
            d0 = _date.fromisoformat(since_ts)
            n_days = max(1, (_date.today() - d0).days)
        except Exception:
            n_days = 15

        h += "<p class='dim'>Dataset: <b>{}</b> tokens com ticks · baseline rec75 = <b>{:.0f}%</b> ({}/{}) · {:.1f}/dia</p>".format(
            n_total, baseline * 100, n_rec75, n_rec, n_total / n_days)

        # ── Helper: mostra uma tabela PASSA / BLOQUEADO ───────────────────────
        def filter_row(label, env_val, condition_blocked, note=""):
            """condition_blocked(row) → True se o filtro BLOQUEARIA este token."""
            blocked = [r for r in rows if r["rec75"] is not None and condition_blocked(r)]
            passes  = [r for r in rows if r["rec75"] is not None and not condition_blocked(r)]

            n_bl   = len(blocked)
            n_pa   = len(passes)
            wr_bl  = sum(1 for r in blocked if r["rec75"]) / n_bl if n_bl else None
            wr_pa  = sum(1 for r in passes  if r["rec75"]) / n_pa if n_pa else None

            # Inclui tokens sem rec75 no count de bloqueados para mostrar impacto total
            n_bl_all = sum(1 for r in rows if condition_blocked(r))
            n_pa_all = n_total - n_bl_all

            problema = wr_bl is not None and wr_pa is not None and wr_bl > wr_pa + 0.05

            out  = "<h3>{}</h3>".format(label)
            out += "<p class='dim'>Valor atual: <b>{}</b>".format(env_val)
            if note:
                out += " · {}".format(note)
            out += "</p>"

            if problema:
                out += "<div class='alert'>⚠️ <b>ATENÇÃO:</b> grupo BLOQUEADO tem rec75 maior ({:.0f}%) que grupo que PASSA ({:.0f}%). ".format(
                    (wr_bl or 0) * 100, (wr_pa or 0) * 100)
                out += "Este filtro está cortando os tokens bons.</div>"

            out += "<table><tr><th>Grupo</th><th>N (total)</th><th>N (c/ rec75)</th><th>rec75</th><th>vs baseline</th><th>Veredicto</th></tr>"

            for grupo, n_all, n_with, wr in [
                ("✅ PASSA o filtro", n_pa_all, n_pa, wr_pa),
                ("🚫 BLOQUEADO",      n_bl_all, n_bl, wr_bl),
            ]:
                if wr is None:
                    out += "<tr><td>{}</td><td>{}</td><td class='dim'>0</td><td>—</td><td>—</td><td class='dim'>sem dados</td></tr>".format(
                        grupo, n_all)
                    continue
                delta = wr - baseline
                col   = "#3fb950" if delta > 0.08 else "#f85149" if delta < -0.08 else "#8b949e"
                if "BLOQUEADO" in grupo:
                    veredicto = "<span style='color:#f85149'>❌ filtro incorreto</span>" if problema else "<span style='color:#3fb950'>✓ correto bloquear</span>"
                else:
                    veredicto = "—"
                out += "<tr><td class='hi'>{}</td><td>{}</td><td>{}</td><td style='color:{}'><b>{:.0f}%</b></td><td style='color:{}'>{:+.0f}pp</td><td>{}</td></tr>".format(
                    grupo, n_all, n_with, col, wr * 100, col, delta * 100, veredicto)
            out += "</table>"
            return out

        # ════════════════════════════════════════════════════════════════════════
        h += "<h2>Filtros em análise</h2>"

        # ── 1. BOUNCE_DROP_MIN = 0.30 ─────────────────────────────────────────
        h += filter_row(
            "1 · BOUNCE_DROP_MIN = 0.30",
            "0.30 (bloqueia dumps < 30%)",
            lambda r: (r["drop_pct"] or 0) < 0.30,
            note="token não caiu 30% da migração → sinal não dispara"
        )

        # ── 2. BOUNCE_MAX_PCT = 1.00 ──────────────────────────────────────────
        # Proxy: bounce_pct_at_signal (primeira vez que o token chegou a +30% do fundo)
        # Se > 1.00 nesse momento, o sinal seria bloqueado imediatamente
        h += filter_row(
            "2 · BOUNCE_MAX_PCT = 1.00",
            "1.00 = 100% (bloqueia bounces > 100% do fundo)",
            lambda r: (r["bounce_pct_at_signal"] or 0) > 1.00,
            note="proxy: bounce_pct na primeira vez que token cruzou +30% nos ticks"
        )

        # ── 3. TRADE_MAX_ELAPSED_SEC = 300 (5 min) ────────────────────────────
        # O bounce dispara quando o token está na subida, logo após o fundo.
        # O elapsed relevante é elapsed_at_bounce30 (quando o sinal teria disparado).
        # Se não temos esse dado, usamos elapsed_to_bottom + secs_bottom_to_bounce30.
        def elapsed_at_signal(r):
            if r["elapsed_at_bounce30"] is not None:
                return r["elapsed_at_bounce30"]
            # fallback: bottom + tempo até bounce
            if r["elapsed_to_bottom"] is not None and r["secs_bottom_to_bounce30"] is not None:
                return r["elapsed_to_bottom"] + r["secs_bottom_to_bounce30"]
            return r["elapsed_to_bottom"]

        h += filter_row(
            "3 · TRADE_MAX_ELAPSED_SEC = 300 (5 min)",
            "300s = 5min (trade bloqueado se sinal dispara > 5min após migração)",
            lambda r: (elapsed_at_signal(r) or 0) > 300,
            note="elapsed no momento em que o sinal teria disparado (primeiro tick com bounce ≥ 30%)"
        )

        # ── 4. BOTTOM_FRESHNESS_SEC = 180 (3 min) ────────────────────────────
        # Proxy: tempo entre o fundo e o primeiro tick com bounce ≥ 30%
        # Se > 180s, A.6 teria bloqueado o sinal
        h += filter_row(
            "4 · BOTTOM_FRESHNESS_SEC = 180 (3 min)",
            "180s = 3min (bloqueia se fundo foi detectado há > 3min)",
            lambda r: (r["secs_bottom_to_bounce30"] or 0) > 180,
            note="proxy: segundos entre o tick de fundo e o primeiro tick com bounce ≥ 30%"
        )

        # ── 5. TRADE_REQUIRE_HELIUS_FEATURES = true ───────────────────────────
        # Não temos esse dado em token_ticks — mostramos a cobertura de pool_quote
        # nos bounce_signals como indicação.
        h += "<h3>5 · TRADE_REQUIRE_HELIUS_FEATURES = true</h3>"
        h += "<p class='dim'>Bloqueia trade quando pool_quote_at_signal ou net_sol_flow estão ausentes no contexto Helius.</p>"
        cur.execute("""
            SELECT
                COUNT(*) AS total,
                SUM(CASE WHEN pool_quote_at_signal IS NOT NULL THEN 1 ELSE 0 END) AS com_pool,
                SUM(CASE WHEN net_sol_flow IS NOT NULL THEN 1 ELSE 0 END) AS com_flow,
                SUM(CASE WHEN pool_quote_at_signal IS NOT NULL
                          AND net_sol_flow IS NOT NULL THEN 1 ELSE 0 END) AS com_ambos
            FROM bounce_signals
            WHERE ts_signal >= %s::timestamptz
        """, (since_ts,))
        bs = cur.fetchone()
        total_bs = bs["total"] or 1
        h += "<table><tr><th>Métrica</th><th>Valor</th><th>Impacto</th></tr>"
        h += "<tr><td>Bounce signals pós-{}</td><td><b>{}</b></td><td class='dim'>amostra</td></tr>".format(since_ts, bs["total"])
        h += "<tr><td>Com pool_quote_at_signal</td><td>{}/{} ({:.0f}%)</td><td class='dim'>{}</td></tr>".format(
            bs["com_pool"], bs["total"],
            100 * (bs["com_pool"] or 0) / total_bs,
            "✅ ok" if (bs["com_pool"] or 0) / total_bs > 0.8 else "⚠️ cobertura baixa")
        h += "<tr><td>Com net_sol_flow</td><td>{}/{} ({:.0f}%)</td><td class='dim'>{}</td></tr>".format(
            bs["com_flow"], bs["total"],
            100 * (bs["com_flow"] or 0) / total_bs,
            "✅ ok" if (bs["com_flow"] or 0) / total_bs > 0.8 else "⚠️ cobertura baixa")
        h += "<tr><td class='hi'>Passariam pelo gate completo</td><td class='hi'>{}/{} ({:.0f}%)</td><td>{}</td></tr>".format(
            bs["com_ambos"], bs["total"],
            100 * (bs["com_ambos"] or 0) / total_bs,
            "<span class='good'>✅ ok</span>" if (bs["com_ambos"] or 0) / total_bs > 0.8
            else "<span class='warn'>⚠️ bloqueia alguns válidos</span>")
        h += "</table>"

        # ── Resumo executivo ──────────────────────────────────────────────────
        h += "<h2>Resumo Executivo</h2>"
        h += "<table><tr><th>Filtro</th><th>N bloqueados (c/ rec75)</th>"
        h += "<th>rec75 bloqueados</th><th>rec75 que passam</th><th>Ação</th></tr>"

        def summary_row(label, condition_blocked):
            bl = [r for r in rows if r["rec75"] is not None and condition_blocked(r)]
            pa = [r for r in rows if r["rec75"] is not None and not condition_blocked(r)]
            wr_bl = sum(1 for r in bl if r["rec75"]) / len(bl) if bl else None
            wr_pa = sum(1 for r in pa if r["rec75"]) / len(pa) if pa else None
            problema = wr_bl is not None and wr_pa is not None and wr_bl > wr_pa + 0.05
            col_bl = "#f85149" if problema else "#8b949e"
            acao = "<span style='color:#f85149'>🔴 REVISAR</span>" if problema else "<span style='color:#3fb950'>✓ ok</span>"
            bl_s = "{:.0f}% n={}".format((wr_bl or 0) * 100, len(bl)) if wr_bl is not None else "—"
            pa_s = "{:.0f}% n={}".format((wr_pa or 0) * 100, len(pa)) if wr_pa is not None else "—"
            return "<tr><td class='hi'>{}</td><td>{}</td><td style='color:{}'>{}</td><td>{}</td><td>{}</td></tr>".format(
                label, len(bl), col_bl, bl_s, pa_s, acao)

        h += summary_row("BOUNCE_DROP_MIN=0.30", lambda r: (r["drop_pct"] or 0) < 0.30)
        h += summary_row("BOUNCE_MAX_PCT=1.00",  lambda r: (r["bounce_pct_at_signal"] or 0) > 1.00)
        h += summary_row("TRADE_MAX_ELAPSED_SEC=300", lambda r: (elapsed_at_signal(r) or 0) > 300)
        h += summary_row("BOTTOM_FRESHNESS_SEC=180", lambda r: (r["secs_bottom_to_bounce30"] or 0) > 180)
        h += "</table>"

        cur.close()
        conn.close()

    except Exception as e:
        import traceback
        h += "<pre style='color:#f85149'>ERRO: {}\n{}</pre>".format(e, traceback.format_exc())

    h += "</body></html>"
    return h


@app.route("/analise/filter-ranges")
def analise_filter_ranges():  # noqa: C901
    """
    Para cada filtro principal, mostra rec75 por faixa (bucket).
    Permite decidir onde cortar: se a faixa bloqueada tem rec75 alto, o threshold está errado.

    Dataset: token_ticks. Outcome: rec75 = max_mc_after >= mc_bottom * 2.275
    """
    import psycopg2.extras

    since_ts = request.args.get("since", "2026-05-26") or "2026-05-26"

    CSS = (
        "<style>"
        "body{background:#0d1117;color:#e6edf3;font:12px/1.6 monospace;padding:20px}"
        "h2{color:#58a6ff;margin-top:28px;border-bottom:1px solid #30363d;padding-bottom:6px}"
        "h3{color:#79c0ff;margin-top:20px}"
        "table{border-collapse:collapse;width:100%;margin-bottom:10px}"
        "th{background:#161b22;padding:6px 10px;text-align:left;font-size:11px;"
        "color:#8b949e;border-bottom:2px solid #30363d}"
        "td{padding:5px 10px;border-bottom:1px solid #21262d;font-size:12px}"
        ".good{color:#3fb950}.warn{color:#f0883e}.bad{color:#f85149}"
        ".dim{color:#8b949e}.hi{color:#e6edf3;font-weight:bold}"
        ".note{background:#1a1f2e;padding:8px 12px;border-left:3px solid #388bfd;margin:8px 0;font-size:11px}"
        ".cur{background:#1f2937;font-weight:bold}"
        "a{color:#58a6ff}"
        "</style>"
    )

    def wr_cell(n_tp, n_total, baseline):
        if n_total == 0:
            return "<td class='dim'>—</td><td class='dim'>—</td><td class='dim'>—</td>"
        wr = n_tp / n_total
        delta = wr - baseline
        col = "#3fb950" if delta > 0.08 else "#f85149" if delta < -0.08 else "#8b949e"
        bar_w = int(wr * 80)
        bar = "<div style='background:{};height:6px;width:{}px;display:inline-block'></div>".format(col, bar_w)
        return "<td>{}/{}</td><td style='color:{}'><b>{:.0f}%</b> {}</td><td style='color:{}'>{:+.0f}pp</td>".format(
            n_tp, n_total, col, wr * 100, bar, col, delta * 100)

    h = "<html><head><meta charset='utf-8'>" + CSS + "</head><body>"
    h += "<h2>📊 Filter Ranges — rec75 por faixa de threshold</h2>"
    h += "<p class='dim'>Período desde <b>{}</b> · ".format(since_ts)
    h += "<a href='?since=2026-05-26'>26/mai</a> | "
    h += "<a href='?since=2026-06-01'>01/jun</a></p>"
    h += "<div class='note'>Cada linha = uma faixa do parâmetro. "
    h += "<b>Linha destacada</b> = threshold atual do Railway. "
    h += "Se faixas bloqueadas pelo threshold atual têm rec75 alto → threshold está errado.</div>"

    try:
        conn = psycopg2.connect(db.DATABASE_URL)
        conn.autocommit = True
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

        cur.execute("""
            WITH tick_window AS (
                SELECT
                    tt.mint, tt.mc, tt.tick_ts,
                    EXTRACT(EPOCH FROM (tt.tick_ts - m.ts_migration)) AS elapsed_sec,
                    m.mc_migration, m.ts_migration
                FROM token_ticks tt
                JOIN migrations m ON m.mint = tt.mint
                WHERE m.ts_migration >= %s::timestamptz
                  AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                  AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'
            ),
            bottom_per_mint AS (
                SELECT DISTINCT ON (mint)
                    mint, mc AS mc_bottom, elapsed_sec AS elapsed_to_bottom, mc_migration
                FROM tick_window
                ORDER BY mint, mc ASC, elapsed_sec ASC
            ),
            time_to_30pct AS (
                SELECT DISTINCT ON (tw.mint)
                    tw.mint,
                    tw.elapsed_sec AS elapsed_at_bounce30,
                    bp.elapsed_to_bottom,
                    (tw.elapsed_sec - bp.elapsed_to_bottom) AS secs_bottom_to_bounce30,
                    (tw.mc - bp.mc_bottom) / bp.mc_bottom AS bounce_pct_at_signal
                FROM tick_window tw
                JOIN bottom_per_mint bp ON bp.mint = tw.mint
                WHERE tw.elapsed_sec > bp.elapsed_to_bottom
                  AND bp.mc_bottom > 0
                  AND (tw.mc - bp.mc_bottom) / bp.mc_bottom >= 0.30
                ORDER BY tw.mint, tw.elapsed_sec ASC
            ),
            max_after_bottom AS (
                SELECT tw.mint, MAX(tw.mc) AS mc_max_after
                FROM tick_window tw
                JOIN bottom_per_mint bp ON bp.mint = tw.mint
                WHERE tw.elapsed_sec > bp.elapsed_to_bottom
                GROUP BY tw.mint
            )
            SELECT
                bp.mint,
                bp.mc_bottom,
                bp.elapsed_to_bottom,
                bp.mc_migration,
                CASE WHEN bp.mc_migration > 0
                    THEN (bp.mc_migration - bp.mc_bottom) / bp.mc_migration
                    ELSE NULL END AS drop_pct,
                mab.mc_max_after,
                CASE WHEN mab.mc_max_after IS NOT NULL AND bp.mc_bottom > 0
                    THEN mab.mc_max_after >= bp.mc_bottom * 2.275
                    ELSE NULL END AS rec75,
                t30.elapsed_at_bounce30,
                t30.secs_bottom_to_bounce30,
                t30.bounce_pct_at_signal
            FROM bottom_per_mint bp
            LEFT JOIN max_after_bottom mab ON mab.mint = bp.mint
            LEFT JOIN time_to_30pct t30 ON t30.mint = bp.mint
            WHERE bp.mc_bottom IS NOT NULL AND bp.mc_bottom > 0
        """, (since_ts,))
        rows = cur.fetchall()
        cur.close()
        conn.close()

        # Apenas tokens com rec75 definido para calcular WR
        scored = [r for r in rows if r["rec75"] is not None]
        n_scored = len(scored)
        n_rec75 = sum(1 for r in scored if r["rec75"])
        baseline = n_rec75 / n_scored if n_scored else 0

        h += "<p class='dim'>Dataset: <b>{}</b> tokens · scored: <b>{}</b> · baseline rec75 = <b>{:.0f}%</b></p>".format(
            len(rows), n_scored, baseline * 100)

        def bucket_table(title, env_key, env_val, buckets, get_val, fmt_label, current_threshold_fn):
            """
            buckets: list of (label, lo, hi) where lo <= val < hi (None = open)
            get_val: fn(row) -> float or None
            current_threshold_fn: fn(lo, hi) -> bool if this bucket is at/above the current cutoff
            """
            out = "<h3>{}</h3>".format(title)
            out += "<p class='dim'>Env var: <b>{}</b> = <b>{}</b></p>".format(env_key, env_val)
            out += "<table><tr><th>Faixa</th><th>N total</th><th>TP/N scored</th>"
            out += "<th>rec75</th><th>vs baseline</th><th>Status</th></tr>"

            for (label, lo, hi) in buckets:
                def in_bucket(r, lo=lo, hi=hi):
                    v = get_val(r)
                    if v is None:
                        return False
                    if lo is not None and v < lo:
                        return False
                    if hi is not None and v >= hi:
                        return False
                    return True

                bucket_rows = [r for r in rows if in_bucket(r)]
                bucket_scored = [r for r in bucket_rows if r["rec75"] is not None]
                n_all = len(bucket_rows)
                n_sc = len(bucket_scored)
                n_tp = sum(1 for r in bucket_scored if r["rec75"])
                is_cur = current_threshold_fn(lo, hi)
                tr_class = " class='cur'" if is_cur else ""

                status_label = "← threshold atual" if is_cur else ""
                out += "<tr{}>".format(tr_class)
                out += "<td class='hi'>{}</td><td>{}</td>".format(label, n_all)
                out += wr_cell(n_tp, n_sc, baseline)
                out += "<td class='dim'>{}</td></tr>".format(status_label)

            out += "</table>"
            return out

        # ── 1. drop_pct (BOUNCE_DROP_MIN) ────────────────────────────────────
        h += bucket_table(
            "1 · drop_pct — BOUNCE_DROP_MIN = 0.30",
            "BOUNCE_DROP_MIN", "0.30",
            [
                ("negativo (token subiu após migração)", None, 0.0),
                ("0–10%  caiu muito pouco",              0.0,  0.10),
                ("10–20% caiu pouco",                    0.10, 0.20),
                ("20–30% caiu moderado",                 0.20, 0.30),
                ("30–40% caiu bastante  ← threshold",    0.30, 0.40),
                ("40–50% dump médio",                    0.40, 0.50),
                ("50–60% dump profundo",                 0.50, 0.60),
                ("60–70% dump severo",                   0.60, 0.70),
                ("70–80% dump extremo",                  0.70, 0.80),
                (">80%   quase rug",                     0.80, None),
            ],
            lambda r: r["drop_pct"],
            lambda lo, hi: "{:.0f}–{:.0f}%".format((lo or 0) * 100, (hi or 100) * 100),
            lambda lo, hi: lo is not None and abs(lo - 0.30) < 0.001,
        )

        # ── 2. bounce_pct_at_signal (BOUNCE_MAX_PCT) ─────────────────────────
        h += bucket_table(
            "2 · bounce_pct_at_signal — BOUNCE_MAX_PCT = 1.00",
            "BOUNCE_MAX_PCT", "1.00",
            [
                ("30–40%  bounce mínimo",     0.30, 0.40),
                ("40–55%  bounce baixo",      0.40, 0.55),
                ("55–70%  bounce médio",      0.55, 0.70),
                ("70–85%  bounce alto",       0.70, 0.85),
                ("85–100% quase dobrou",      0.85, 1.00),
                (">100%  dobrou ← threshold", 1.00, None),
            ],
            lambda r: r["bounce_pct_at_signal"],
            lambda lo, hi: "",
            lambda lo, hi: lo is not None and abs(lo - 1.00) < 0.001,
        )

        # ── 3. elapsed_at_bounce30 (TRADE_MAX_ELAPSED_SEC) ───────────────────
        def elapsed_signal(r):
            if r["elapsed_at_bounce30"] is not None:
                return r["elapsed_at_bounce30"]
            if r["elapsed_to_bottom"] is not None and r["secs_bottom_to_bounce30"] is not None:
                return r["elapsed_to_bottom"] + r["secs_bottom_to_bounce30"]
            return r["elapsed_to_bottom"]

        h += bucket_table(
            "3 · elapsed ao sinal — TRADE_MAX_ELAPSED_SEC = 300 (5min)",
            "TRADE_MAX_ELAPSED_SEC", "300",
            [
                ("0–2min   (0–120s)",          0,   120),
                ("2–5min   (120–300s) ← atual", 120, 300),
                ("5–8min   (300–480s)",          300, 480),
                ("8–12min  (480–720s)",          480, 720),
                ("12–15min (720–900s)",          720, 900),
                ("15–20min (900–1200s)",         900, 1200),
                (">20min   (>1200s)",            1200, None),
            ],
            elapsed_signal,
            lambda lo, hi: "",
            lambda lo, hi: lo is not None and abs(lo - 120) < 1,
        )

        # ── 4. secs_bottom_to_bounce30 (BOTTOM_FRESHNESS_SEC) ────────────────
        h += bucket_table(
            "4 · secs fundo→sinal — BOTTOM_FRESHNESS_SEC = 180 (3min)",
            "BOTTOM_FRESHNESS_SEC", "180",
            [
                ("0–30s    fundo instantâneo",   0,   30),
                ("30–60s   1 minuto",            30,  60),
                ("60–120s  2 minutos",           60,  120),
                ("120–180s 3 min ← threshold",  120, 180),
                ("180–300s 3–5 minutos",         180, 300),
                ("300–600s 5–10 minutos",        300, 600),
                (">600s    >10 minutos",         600, None),
            ],
            lambda r: r["secs_bottom_to_bounce30"],
            lambda lo, hi: "",
            lambda lo, hi: lo is not None and abs(lo - 120) < 1,
        )

        # ── Tabela de correlação drop_pct × elapsed ───────────────────────────
        h += "<h2>Correlação drop_pct × elapsed ao sinal</h2>"
        h += "<div class='note'>Grid 2D: cada célula = rec75 nessa combinação. "
        h += "Mostra onde está o edge real — dump profundo rápido vs dump leve tardio.</div>"

        drop_buckets  = [(">0–20%", 0.0, 0.20), ("20–40%", 0.20, 0.40),
                         ("40–60%", 0.40, 0.60), (">60%", 0.60, None)]
        elapsed_buckets = [("0–2min", 0, 120), ("2–5min", 120, 300),
                           ("5–10min", 300, 600), ("10–15min", 600, 900), (">15min", 900, None)]

        h += "<table><tr><th>drop \\ elapsed</th>"
        for (el, _, _) in elapsed_buckets:
            h += "<th>{}</th>".format(el)
        h += "</tr>"

        for (dl, dlo, dhi) in drop_buckets:
            h += "<tr><td class='hi'>{}</td>".format(dl)
            for (el, elo, ehi) in elapsed_buckets:
                cell = [r for r in scored
                        if (r["drop_pct"] or 0) >= (dlo or 0)
                        and ((dhi is None) or (r["drop_pct"] or 0) < dhi)
                        and (elapsed_signal(r) or 0) >= elo
                        and ((ehi is None) or (elapsed_signal(r) or 0) < ehi)]
                n_c = len(cell)
                n_tp_c = sum(1 for r in cell if r["rec75"])
                if n_c == 0:
                    h += "<td class='dim'>—</td>"
                else:
                    wr_c = n_tp_c / n_c
                    col = "#3fb950" if wr_c > baseline + 0.08 else "#f85149" if wr_c < baseline - 0.08 else "#8b949e"
                    h += "<td style='color:{}'><b>{:.0f}%</b><br><span class='dim'>n={}</span></td>".format(
                        col, wr_c * 100, n_c)
            h += "</tr>"
        h += "</table>"

    except Exception as e:
        import traceback
        h += "<pre style='color:#f85149'>ERRO: {}\n{}</pre>".format(e, traceback.format_exc())

    h += "</body></html>"
    return h


@app.route("/analise/filtros-simples")
def analise_filtros_simples():  # noqa: C901
    """
    Dashboard simplificado para análise de filtros — linguagem de negócio.
    """
    import psycopg2.extras
    from datetime import date as _date

    since_ts = request.args.get("since", "2026-05-26") or "2026-05-26"

    CSS = (
        "<style>"
        "body{background:#0f1117;color:#e2e8f0;font:14px/1.8 -apple-system,sans-serif;padding:32px;max-width:960px;margin:0 auto}"
        "h1{color:#fff;font-size:24px;margin-bottom:4px}"
        "h2{color:#60a5fa;font-size:18px;margin-top:40px;margin-bottom:4px;border-bottom:1px solid #1e293b;padding-bottom:8px}"
        "h3{color:#94a3b8;font-size:13px;font-weight:normal;margin:0 0 16px 0}"
        "table{border-collapse:collapse;width:100%;margin:16px 0 24px 0}"
        "th{background:#1e293b;padding:10px 14px;text-align:left;font-size:12px;color:#64748b;font-weight:600;letter-spacing:.05em;text-transform:uppercase}"
        "td{padding:9px 14px;border-bottom:1px solid #1e293b;font-size:13px;vertical-align:middle}"
        "tr:hover td{background:#161b27}"
        ".highlight{background:#1a2436!important}"
        ".highlight td{font-weight:600}"
        ".badge-green{background:#14532d;color:#4ade80;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700}"
        ".badge-yellow{background:#422006;color:#fbbf24;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700}"
        ".badge-red{background:#3b0000;color:#f87171;padding:3px 10px;border-radius:20px;font-size:12px;font-weight:700}"
        ".badge-gray{background:#1e293b;color:#64748b;padding:3px 10px;border-radius:20px;font-size:12px}"
        ".card{background:#1e293b;border-radius:10px;padding:18px 22px;margin:16px 0}"
        ".card p{margin:4px 0;color:#94a3b8;font-size:13px}"
        ".card strong{color:#e2e8f0}"
        ".explain{background:#172033;border-left:3px solid #3b82f6;padding:12px 16px;border-radius:0 6px 6px 0;margin:12px 0 20px;font-size:13px;color:#94a3b8}"
        ".explain b{color:#93c5fd}"
        ".warn-box{background:#1f1208;border-left:3px solid #f59e0b;padding:12px 16px;border-radius:0 6px 6px 0;margin:12px 0;font-size:13px;color:#d4a35a}"
        ".action-box{background:#0c1f1a;border-left:3px solid #34d399;padding:12px 16px;border-radius:0 6px 6px 0;margin:12px 0;font-size:13px;color:#6ee7b7}"
        ".stat{display:inline-block;margin-right:28px}"
        ".stat .val{font-size:28px;font-weight:700;color:#fff}"
        ".stat .lbl{font-size:11px;color:#64748b;text-transform:uppercase;letter-spacing:.06em}"
        ".dim{color:#475569}"
        ".arrow{color:#f59e0b;font-size:16px}"
        "a{color:#60a5fa;text-decoration:none}"
        ".tag-atual{background:#1d2d1a;color:#4ade80;font-size:11px;padding:2px 8px;border-radius:4px;margin-left:6px}"
        ".tag-block{background:#2d1a1a;color:#f87171;font-size:11px;padding:2px 8px;border-radius:4px;margin-left:6px}"
        ".pct-bar{display:inline-block;height:8px;border-radius:4px;margin-left:8px;vertical-align:middle}"
        "</style>"
    )

    h = "<html><head><meta charset='utf-8'><title>Análise de Filtros — NeideBOT</title>" + CSS + "</head><body>"

    # ── Cabeçalho ─────────────────────────────────────────────────────────────
    h += "<h1>🤖 NeideBOT — Análise de Filtros</h1>"
    h += "<p class='dim'>Dados desde {} &nbsp;·&nbsp; ".format(since_ts)
    h += "<a href='?since=2026-05-26'>desde 26/mai</a> &nbsp;|&nbsp; "
    h += "<a href='?since=2026-06-01'>desde 01/jun</a></p>"

    try:
        conn = psycopg2.connect(db.DATABASE_URL)
        conn.autocommit = True
        cur = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)

        cur.execute("""
            WITH tick_window AS (
                SELECT tt.mint, tt.mc, tt.tick_ts,
                    EXTRACT(EPOCH FROM (tt.tick_ts - m.ts_migration)) AS elapsed_sec,
                    m.mc_migration, m.ts_migration
                FROM token_ticks tt
                JOIN migrations m ON m.mint = tt.mint
                WHERE m.ts_migration >= %s::timestamptz
                  AND tt.tick_ts > m.ts_migration + INTERVAL '90 seconds'
                  AND tt.tick_ts < m.ts_migration + INTERVAL '60 minutes'
            ),
            bottom_per_mint AS (
                SELECT DISTINCT ON (mint) mint,
                    mc AS mc_bottom, elapsed_sec AS elapsed_to_bottom, mc_migration
                FROM tick_window ORDER BY mint, mc ASC, elapsed_sec ASC
            ),
            time_to_30pct AS (
                SELECT DISTINCT ON (tw.mint)
                    tw.mint, tw.elapsed_sec AS elapsed_at_bounce30,
                    bp.elapsed_to_bottom,
                    (tw.elapsed_sec - bp.elapsed_to_bottom) AS secs_bottom_to_bounce30,
                    (tw.mc - bp.mc_bottom) / bp.mc_bottom AS bounce_pct_at_signal
                FROM tick_window tw
                JOIN bottom_per_mint bp ON bp.mint = tw.mint
                WHERE tw.elapsed_sec > bp.elapsed_to_bottom AND bp.mc_bottom > 0
                  AND (tw.mc - bp.mc_bottom) / bp.mc_bottom >= 0.30
                ORDER BY tw.mint, tw.elapsed_sec ASC
            ),
            max_after_bottom AS (
                SELECT tw.mint, MAX(tw.mc) AS mc_max_after
                FROM tick_window tw
                JOIN bottom_per_mint bp ON bp.mint = tw.mint
                WHERE tw.elapsed_sec > bp.elapsed_to_bottom GROUP BY tw.mint
            )
            SELECT bp.mint, bp.mc_bottom, bp.elapsed_to_bottom, bp.mc_migration,
                CASE WHEN bp.mc_migration > 0
                    THEN (bp.mc_migration - bp.mc_bottom) / bp.mc_migration ELSE NULL END AS drop_pct,
                mab.mc_max_after,
                CASE WHEN mab.mc_max_after IS NOT NULL AND bp.mc_bottom > 0
                    THEN mab.mc_max_after >= bp.mc_bottom * 2.275 ELSE NULL END AS rec75,
                t30.elapsed_at_bounce30, t30.secs_bottom_to_bounce30, t30.bounce_pct_at_signal
            FROM bottom_per_mint bp
            LEFT JOIN max_after_bottom mab ON mab.mint = bp.mint
            LEFT JOIN time_to_30pct t30 ON t30.mint = bp.mint
            WHERE bp.mc_bottom IS NOT NULL AND bp.mc_bottom > 0
        """, (since_ts,))
        rows = cur.fetchall()
        cur.close()
        conn.close()

        scored = [r for r in rows if r["rec75"] is not None]
        n_sc = len(scored)
        n_rec75 = sum(1 for r in scored if r["rec75"])
        baseline = n_rec75 / n_sc if n_sc else 0

        try:
            d0 = _date.fromisoformat(since_ts)
            n_days = max(1, (_date.today() - d0).days)
        except Exception:
            n_days = 15

        def elapsed_signal(r):
            if r["elapsed_at_bounce30"] is not None:
                return r["elapsed_at_bounce30"]
            if r["elapsed_to_bottom"] is not None and r["secs_bottom_to_bounce30"] is not None:
                return r["elapsed_to_bottom"] + r["secs_bottom_to_bounce30"]
            return r["elapsed_to_bottom"]

        # ── Resumo geral ──────────────────────────────────────────────────────
        h += "<div class='card'>"
        h += "<div>"
        h += "<span class='stat'><div class='val'>{}</div><div class='lbl'>Tokens analisados</div></span>".format(len(rows))
        h += "<span class='stat'><div class='val'>{:.0f}/dia</div><div class='lbl'>Frequência</div></span>".format(len(rows) / n_days)
        h += "<span class='stat'><div class='val' style='color:#4ade80'>{:.0f}%</div><div class='lbl'>Taxa base de sucesso</div></span>".format(baseline * 100)
        h += "<span class='stat'><div class='val'>{}</div><div class='lbl'>Período (dias)</div></span>".format(n_days)
        h += "</div>"
        h += "<p style='margin-top:14px'><b>Como ler:</b> "
        h += '"Taxa de sucesso" = % dos tokens que chegaram a +75% acima do ponto de entrada simulado nos 60 minutos após a migração. '
        h += "Taxa base de <b>{:.0f}%</b> é o resultado SEM nenhum filtro extra.</p>".format(baseline * 100)
        h += "</div>"

        # ── Helper para tabela de faixas ──────────────────────────────────────
        def faixa_table(buckets, get_val, cur_lo, note_fn=None):
            out = "<table><tr><th>Faixa</th><th>Tokens</th><th>Taxa de sucesso</th><th>vs média geral</th><th></th></tr>"
            for (label, lo, hi, descr) in buckets:
                def in_b(r, lo=lo, hi=hi):
                    v = get_val(r)
                    if v is None:
                        return False
                    if lo is not None and v < lo:
                        return False
                    if hi is not None and v >= hi:
                        return False
                    return True

                br = [r for r in scored if in_b(r)]
                n_b = len(br)
                n_tp = sum(1 for r in br if r["rec75"])
                wr = n_tp / n_b if n_b else None

                is_cur = (lo is not None and cur_lo is not None and abs(lo - cur_lo) < 0.001)
                tr_cls = " class='highlight'" if is_cur else ""

                tag = ""
                if is_cur:
                    tag = "<span class='tag-atual'>← valor atual</span>"

                if wr is None:
                    out += "<tr{}><td>{}{}</td><td class='dim'>0</td><td class='dim'>—</td><td class='dim'>—</td><td></td></tr>".format(
                        tr_cls, label, tag)
                    continue

                delta = wr - baseline
                if delta > 0.08:
                    badge = "<span class='badge-green'>✓ {:.0f}%</span>".format(wr * 100)
                elif delta < -0.08:
                    badge = "<span class='badge-red'>✗ {:.0f}%</span>".format(wr * 100)
                else:
                    badge = "<span class='badge-yellow'>{:.0f}%</span>".format(wr * 100)

                delta_str = "{:+.0f}pp".format(delta * 100)
                delta_col = "#4ade80" if delta > 0.08 else "#f87171" if delta < -0.08 else "#94a3b8"
                bar_w = int(wr * 120)
                bar = "<div class='pct-bar' style='width:{}px;background:{}'></div>".format(bar_w, delta_col)

                note = ""
                if note_fn:
                    note = note_fn(lo, hi, wr, n_b)

                out += "<tr{}>".format(tr_cls)
                out += "<td>{}{}<br><span class='dim' style='font-size:11px'>{}</span></td>".format(label, tag, descr)
                out += "<td>{}</td>".format(n_b)
                out += "<td>{}{}</td>".format(badge, bar)
                out += "<td style='color:{}'>{}</td>".format(delta_col, delta_str)
                out += "<td class='dim' style='font-size:11px'>{}</td>".format(note)
                out += "</tr>"
            out += "</table>"
            return out

        # ══════════════════════════════════════════════════════════════════════
        # FILTRO 1 — BOUNCE_DROP_MIN
        # ══════════════════════════════════════════════════════════════════════
        h += "<h2>📉 Filtro 1 — Queda mínima exigida após a migração</h2>"
        h += "<h3>Valor atual no Railway: <b>BOUNCE_DROP_MIN = 0.30</b> (exige queda de pelo menos 30%)</h3>"
        h += "<div class='explain'>"
        h += "<b>O que é:</b> quando um token migra do Pump.fun para a DEX, o preço costuma cair primeiro (os primeiros compradores saem). "
        h += "Este filtro define: 'só compro se o token já caiu pelo menos X% desde que chegou na DEX'. "
        h += "<br><b>Problema identificado:</b> os dados mostram que tokens que caíram pouco (10–30%) têm taxa de sucesso muito maior do que os que caíram muito (>40%). "
        h += "O bot está ignorando os melhores e comprando os piores."
        h += "</div>"

        h += faixa_table(
            [
                ("Subiu após migração",         None, 0.0,  "token não caiu — veio comprando desde o início"),
                ("Caiu 0 a 10%",                0.0,  0.10, "caiu muito pouco — demanda forte"),
                ("Caiu 10% a 20%",              0.10, 0.20, "caiu pouco — ainda demanda saudável"),
                ("Caiu 20% a 30%",              0.20, 0.30, "caiu moderado — ponto de entrada razoável"),
                ("Caiu 30% a 40%",              0.30, 0.40, "LIMITE ATUAL — passa a partir daqui"),
                ("Caiu 40% a 50%",              0.40, 0.50, "caiu bastante"),
                ("Caiu 50% a 60%",              0.50, 0.60, "dump médio"),
                ("Caiu 60% a 70%",              0.60, 0.70, "dump profundo"),
                ("Caiu 70% a 80%",              0.70, 0.80, "dump severo"),
                ("Caiu mais de 80%",            0.80, None, "quase rug — raramente recupera"),
            ],
            lambda r: r["drop_pct"],
            0.30,
        )

        h += "<div class='warn-box'>⚠️ <b>O que os dados dizem:</b> "
        h += "tokens que caíram 10–30% têm taxa de sucesso de 38–46% (quase o dobro da média). "
        h += "Tokens que caíram 30–50% têm 12–17% (abaixo da média). "
        h += "O filtro atual está bloqueando os melhores e aceitando os piores.</div>"
        h += "<div class='action-box'>✅ <b>Sugestão:</b> mudar <code>BOUNCE_DROP_MIN</code> de <b>0.30</b> para <b>0.10</b>. "
        h += "Isso inclui tokens que caíram a partir de 10% — onde está o edge real.</div>"

        # ══════════════════════════════════════════════════════════════════════
        # FILTRO 2 — TRADE_MAX_ELAPSED_SEC
        # ══════════════════════════════════════════════════════════════════════
        h += "<h2>⏱️ Filtro 2 — Tempo máximo após a migração para comprar</h2>"
        h += "<h3>Valor atual no Railway: <b>TRADE_MAX_ELAPSED_SEC = 300</b> (só compra se o sinal vier nos primeiros 5 minutos)</h3>"
        h += "<div class='explain'>"
        h += "<b>O que é:</b> após a migração, o bot monitora o token. Quando detecta uma recuperação do preço, tenta comprar. "
        h += "Este filtro diz: 'só executo a compra se esse sinal chegou em menos de X segundos após a migração'. "
        h += "<br><b>Problema identificado:</b> os dados mostram que os melhores resultados estão entre 8 e 15 minutos — muito depois dos 5 min do filtro atual. "
        h += "Estamos comprando numa janela que tem taxa de sucesso média, e ignorando a janela com maior taxa de sucesso."
        h += "</div>"

        h += faixa_table(
            [
                ("0 a 2 minutos",            0,    120,  "sinal imediato — geralmente armadilha"),
                ("2 a 5 minutos",            120,  300,  "LIMITE ATUAL — aceita até aqui"),
                ("5 a 8 minutos",            300,  480,  "levemente melhor que a janela atual"),
                ("8 a 12 minutos",           480,  720,  "melhor janela da amostra"),
                ("12 a 15 minutos",          720,  900,  "excelente — poucos tokens mas alta taxa"),
                ("15 a 20 minutos",          900,  1200, "começa a cair"),
                ("Mais de 20 minutos",       1200, None, "tarde demais — token perdeu força"),
            ],
            elapsed_signal,
            120,
        )

        h += "<div class='warn-box'>⚠️ <b>O que os dados dizem:</b> "
        h += "74% dos sinais do bot chegam APÓS os 5 minutos e são bloqueados. "
        h += "A janela 8–15 min tem taxa de sucesso de 41–100%. "
        h += "Estamos descartando a maioria dos sinais e os melhores.</div>"
        h += "<div class='action-box'>✅ <b>Sugestão:</b> mudar <code>TRADE_MAX_ELAPSED_SEC</code> de <b>300</b> para <b>900</b>. "
        h += "Isso abre a janela para 15 minutos — capturando o sweet spot 8–15 min.</div>"

        # ══════════════════════════════════════════════════════════════════════
        # FILTRO 3 — BOTTOM_FRESHNESS_SEC
        # ══════════════════════════════════════════════════════════════════════
        h += "<h2>🕐 Filtro 3 — Quão recente foi o fundo antes do sinal</h2>"
        h += "<h3>Valor atual no Railway: <b>BOTTOM_FRESHNESS_SEC = 180</b> (o fundo tem que ter acontecido nos últimos 3 minutos)</h3>"
        h += "<div class='explain'>"
        h += "<b>O que é:</b> quando o bot detecta que o preço subiu 30% a partir do fundo, ele verifica: 'esse fundo foi recente?' "
        h += "Se o fundo aconteceu há muito tempo e o preço está subindo lentamente, o sinal é bloqueado. "
        h += "<br><b>Problema identificado:</b> o filtro de 3 minutos está bloqueando tokens onde o sinal demora um pouco mais a aparecer (3–10 min após o fundo), mas esses tokens têm taxa de sucesso acima da média."
        h += "</div>"

        h += faixa_table(
            [
                ("Sinal em até 30 segundos",      0,   30,  "fundo e subida quase simultâneos"),
                ("Sinal em 30s a 1 minuto",       30,  60,  "recuperação rápida — boa"),
                ("Sinal em 1 a 2 minutos",        60,  120, "ritmo saudável — melhor resultado"),
                ("Sinal em 2 a 3 minutos",        120, 180, "LIMITE ATUAL — aceita até aqui"),
                ("Sinal em 3 a 5 minutos",        180, 300, "acima da média — bloqueado atualmente"),
                ("Sinal em 5 a 10 minutos",       300, 600, "acima da média — bloqueado atualmente"),
                ("Sinal depois de 10 minutos",    600, None, "recovery muito lento — raramente funciona"),
            ],
            lambda r: r["secs_bottom_to_bounce30"],
            120,
        )

        h += "<div class='warn-box'>⚠️ <b>O que os dados dizem:</b> "
        h += "a faixa de 3–10 minutos tem taxa de sucesso de 33% (acima da média de 24%). "
        h += "O único grupo realmente ruim é acima de 10 minutos (0%). "
        h += "O corte em 3 minutos está muito apertado.</div>"
        h += "<div class='action-box'>✅ <b>Sugestão:</b> mudar <code>BOTTOM_FRESHNESS_SEC</code> de <b>180</b> para <b>600</b>. "
        h += "Bloqueia apenas recuperações muito lentas (>10 min após o fundo), que de fato não funcionam.</div>"

        # ══════════════════════════════════════════════════════════════════════
        # RESUMO FINAL
        # ══════════════════════════════════════════════════════════════════════
        h += "<h2>📋 Resumo — O que mudar</h2>"

        changes = [
            ("BOUNCE_DROP_MIN",      "0.30", "0.10",
             "Inclui tokens que caíram 10–30% — taxa de sucesso 38–46% vs 12–17% atual"),
            ("TRADE_MAX_ELAPSED_SEC","300",  "900",
             "Abre janela para 15 min — captura o sweet spot 8–15 min com 41%+ de sucesso"),
            ("BOTTOM_FRESHNESS_SEC", "180",  "600",
             "Permite recuperações mais lentas (até 10 min após fundo) que têm 33% de sucesso"),
        ]

        h += "<table><tr><th>Parâmetro</th><th>Valor atual</th><th>Sugerido</th><th>Motivo</th></tr>"
        for (param, cur_v, new_v, motivo) in changes:
            h += "<tr><td class='hi'><code>{}</code></td>".format(param)
            h += "<td><span class='badge-red'>{}</span></td>".format(cur_v)
            h += "<td><span class='badge-green'>{}</span></td>".format(new_v)
            h += "<td class='dim'>{}</td></tr>".format(motivo)
        h += "</table>"

        h += "<div class='card'>"
        h += "<p><strong>Importante:</strong> essas três mudanças são apenas nas variáveis de ambiente do Railway — zero alteração de código.</p>"
        h += "<p>Os dados acima são de {} tokens reais monitorados pelo bot nos últimos {} dias. ".format(len(rows), n_days)
        h += "Cada token foi acompanhado por 60 minutos após a migração.</p>"
        h += "<p><strong>Próximo passo:</strong> aplicar as mudanças, acumular 30+ trades com os novos parâmetros e medir o impacto real na taxa de sucesso.</p>"
        h += "</div>"

    except Exception as e:
        import traceback
        h += "<pre style='color:#f87171'>ERRO: {}\n{}</pre>".format(e, traceback.format_exc())

    h += "</body></html>"
    return h


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.getenv("PORT", 5000)), debug=False)

